import {
  ApplicationQuestions,
  Configuration,
  InsurancePolicy,
} from '@crucible-risk/sku-api-schema';
import {History} from 'history';

import {createClient} from '/lib/api';
import {UnknownErrorException} from '/lib/exceptions';
import {getSession} from '/lib/session';
import {Preloader} from '/lib/withPreloadedDataPage';
import {clonePolicy} from '/lib/clone-policy';

export interface ConfirmationPageProps {
  configuration: Configuration | null;
  policy: InsurancePolicy;
  applicationQuestions: ApplicationQuestions;
  sessionId: string;
}

export type LoaderProps = {
  history: History;
};

export const confirmationPageDataLoader: Preloader<
  ConfirmationPageProps,
  LoaderProps
> = (query: URLSearchParams, {history}): Promise<ConfirmationPageProps> => {
  const sessionId = query.get('session');
  if (!sessionId) {
    throw new UnknownErrorException();
  }

  const client = createClient(getSession(sessionId));

  return client
    .getInsurancePolicy()
    .then((response) => {
      if (response.ok) {
        return response.data;
      }
      throw new UnknownErrorException();
    })
    .then((policy) => {
      // If the policy is not in an incomplete state, it means the user has
      // likely hit back after attempting to issue their quote.  They cannot
      // edit it unless we recreate it with the same properties.
      if (policy.lifecycle_state !== 'INCOMPLETE') {
        return clonePolicy(policy).then((policy) => {
          history.replace({
            pathname: history.location.pathname,
            search: `?session=${policy.uuid}`,
          });

          return policy;
        });
      }
      return policy;
    })
    .then((policy) =>
      client.getApplicationQuestions().then(({ok, data}) => {
        if (!ok) {
          throw new UnknownErrorException();
        }

        const requiredQuestions = data.application_questions.filter(
          (q) => q.required,
        );

        return {
          sessionId,
          policy,
          applicationQuestions: {
            application_questions: requiredQuestions,
            status: data.status,
          },
          configuration: policy.selected_configuration,
        };
      }),
    );
};
