import React from 'react';
import {useFela} from 'react-fela';

import {scale} from './spacing.config';

import {
  paddingTopStyle,
  paddingRightStyle,
  paddingBottomStyle,
  paddingLeftStyle,
  widthStyle,
  heightStyle,
  fillStyle,
} from './spacing.fela';

export interface Props extends React.HTMLAttributes<HTMLDivElement> {
  around?: keyof typeof scale;

  horizontal?: keyof typeof scale;
  vertical?: keyof typeof scale;

  top?: keyof typeof scale;
  right?: keyof typeof scale;
  bottom?: keyof typeof scale;
  left?: keyof typeof scale;

  width?: keyof typeof scale;
  height?: keyof typeof scale;

  fill?: boolean;
}

export const SpacingRefComponent = (
  props: Props,
  ref: React.Ref<HTMLDivElement>,
) => {
  const {
    around,
    horizontal = around,
    vertical = around,
    top = vertical,
    right = horizontal,
    bottom = vertical,
    left = horizontal,
    width,
    height,
    fill,
    ...rest
  } = props;

  const {css} = useFela({top, right, bottom, left, width, height, fill});

  return (
    <div
      ref={ref}
      {...rest}
      className={css(
        paddingTopStyle,
        paddingRightStyle,
        paddingBottomStyle,
        paddingLeftStyle,
        widthStyle,
        heightStyle,
        fillStyle,
      )}
    />
  );
};

export const Spacing = React.forwardRef(SpacingRefComponent);

export type SpacingAttributes = JSX.LibraryManagedAttributes<
  typeof Spacing,
  Props
>;
