import {StyleFunction} from 'react-fela';

import {interactiveBorderRadius} from '@crucible-risk/theme';

import {intents} from './alert.config';

export const alertStyle: StyleFunction<{}, {intent: keyof typeof intents}> = ({
  intent = 'primary',
}) => {
  return {
    borderRadius: interactiveBorderRadius,
    display: 'flex',
    width: '100%',
    padding: 16,

    background: intents[intent]?.color,
  };
};

export const contentStyle: StyleFunction<
  {},
  {intent: keyof typeof intents}
> = ({intent = 'primary'}) => {
  return {
    display: 'flex',
    flexWrap: 'wrap',
    flex: '1 1 auto',
    marginTop: -16,
    marginRight: -16,
    color: intents[intent]?.textColor,
  };
};

export const messageStyle: StyleFunction<{}, {}> = () => {
  return {
    flex: 'auto',
    flexBasis: 320,
    marginRight: 16,
    marginLeft: 16,
    marginTop: 16,
  };
};

export const actionsStyle: StyleFunction<{}, {}> = () => {
  return {
    display: 'flex',
    justifyContent: 'flex-end',
    marginLeft: 16,
    marginRight: 16,
    marginTop: 16,
  };
};

export const closeStyle: StyleFunction<{}, {}> = () => {
  return {
    marginLeft: 32,
  };
};

export const iconStyle: StyleFunction<{}, {intent: keyof typeof intents}> = ({
  intent = 'primary',
}) => {
  return {
    color: intents[intent]?.iconColor,
  };
};

export const rawStyle: StyleFunction<{}, {}> = () => {
  return {
    background: 'rgba(255,255,255, 0.5)',
    padding: '8px 16px',
    borderRadius: '4px',
    border: '1px solid rgba(255,255,255, 0.9)',
    marginTop: '10px',
  };
};
