import {
  useSegmentTrack,
  useSentryCaptureException,
} from '@crucible-risk/react-monitoring';
import React from 'react';
import {mapUnknownToString} from '/utils/mapUnknownToString';
import {ExpiredJwtError} from '/lib/exceptions';
import {LinkButton} from '@crucible-risk/button';
import {UseSupportChat} from '/lib/chat';

/*
When reflowing a JSON web token, this component mounts if an error occurred
  decoding the token.
*/

interface ReflowJwtDecodeErrorProps {
  readonly error: unknown;
  readonly jwt: string;
}

export function ReflowJwtDecodeError({
  error,
  jwt,
}: ReflowJwtDecodeErrorProps): React.ReactElement {
  // Contexts
  const track = useSegmentTrack();
  const captureException = useSentryCaptureException();
  const {show: openChat} = UseSupportChat();

  // States
  const errorStr: string = mapUnknownToString(error);
  const isExpiredJwt = error instanceof ExpiredJwtError;

  // Effects
  React.useEffect((): void => {
    // Don't send ExpiredJwtError to Sentry - it's an expected error
    if (!isExpiredJwt) {
      void captureException(errorStr, {
        extra: {
          jwt,
        },
      });
    }
    void track(
      isExpiredJwt ? 'Reflow JWT expired' : 'Reflow JWT decode failed',
      {
        error: errorStr,
        jwt,
      },
    );
  }, [captureException, errorStr, jwt, track, isExpiredJwt]);

  if (isExpiredJwt) {
    return (
      <>
        <p>This link has expired.</p>
        <p>
          Email links are valid for 60 days. Please{' '}
          <LinkButton onClick={openChat}>contact us</LinkButton> to request a
          new link.
        </p>
      </>
    );
  }

  return (
    <>
      <p>An error occurred decoding your session:</p>
      <p>{errorStr}</p>
      <p>
        If you believe you reached this page in error, please contact a customer
        representative.
      </p>
    </>
  );
}
