import {Record, Literal, Null, String, Static} from 'runtypes';

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/api/quick_search.py#L92
export const SearchAccountSchema = Record({
  city: String.Or(Null),
  name: String,
  state: String.Or(Null),
  type: Literal('account'),
  uuid: String,
});

export type SearchAccount = Static<typeof SearchAccountSchema>;
