export interface CompanyAddress {
  streetLine1: string;
  streetLine2: string;
  city: string;
  state: string;
  zipcode: string;
}

export interface PlaceSuggestion {
  description: string;
  place_id: string;
}

const normalizePlace = (place: any): CompanyAddress => {
  const componentForm: any = {
    street_number: 'short_name',
    route: 'long_name',
    subpremise: 'long_name',
    locality: 'long_name',
    sublocality: 'long_name',
    neighborhood: 'long_name',
    administrative_area_level_1: 'short_name',
    administrative_area_level_2: 'short_name',
    postal_code: 'short_name',
  };
  const gMapToForm: any = {
    street_number: 'streetLine_1',
    route: 'streetLine_1',
    subpremise: 'streetLine_2',
    locality: 'city',
    sublocality: 'city',
    neighborhood: 'city',
    administrative_area_level_1: 'state',
    administrative_area_level_2: 'sub_administrative_area',
    postal_code: 'zipcode',
  };

  const normalizedPlace: CompanyAddress = {
    streetLine1: '',
    streetLine2: '',
    city: '',
    state: '',
    zipcode: '',
  };

  let street = '';
  for (let i = 0; i < place.address_components.length; i++) {
    const addressType = place.address_components[i].types.filter(
      (t: string) => !!componentForm[t],
    )[0];
    if (componentForm[addressType]) {
      const val = place.address_components[i][componentForm[addressType]];
      if (addressType === 'street_number') {
        street = street ? `${val} ${street}` : val;
      } else if (addressType === 'route') {
        street = street ? `${street} ${val}` : val;
      } else {
        normalizedPlace[gMapToForm[addressType] as keyof CompanyAddress] = val;
      }
    }
  }
  normalizedPlace.streetLine1 = street;
  return normalizedPlace;
};

declare global {
  interface Window {
    google: any;
  }
}

export type AddressAutoCompleteService = (
  input: string,
) => Promise<Array<PlaceSuggestion>>;

export type AddressGeocoderService = (
  placeId: string,
) => Promise<CompanyAddress>;

export const addressAutocompleteService: AddressAutoCompleteService = (
  value,
) => {
  if (!value) {
    return Promise.resolve([]);
  }

  return new Promise((resolve, reject) => {
    if (!window || !window.google) {
      reject();
    }

    const autocompleteService = new window.google.maps.places.AutocompleteService();

    autocompleteService.getPlacePredictions(
      {
        input: value,
        componentRestrictions: {country: ['us']},
      },
      (results: any) => {
        resolve(results);
      },
    );
  });
};

export const addressGeocoderService: AddressGeocoderService = (placeId) => {
  return new Promise((resolve, reject) => {
    if (!window || !window.google) {
      reject();
    }

    const geocoder = new window.google.maps.Geocoder();

    geocoder.geocode({placeId}, (results: any, status: any) => {
      if (status !== 'OK') {
        reject(status);
      }

      resolve(normalizePlace(results[0]));
    });
  });
};
