import React, {Fragment} from 'react';
import {useFela} from 'react-fela';

import {Typography} from '@crucible-risk/typography';
import {LinkButton} from '@crucible-risk/button';
import {Spacing} from '@crucible-risk/spacing';
import {colors} from '@crucible-risk/theme';
import {DownloadIcon, PencilIcon} from '@crucible-risk/icon';
import {Currency} from '@crucible-risk/sku-api-schema';
import {useA11yKeyEvents} from '@crucible-risk/a11y-key-events-hook';
import {Spinner} from '@crucible-risk/spinner';

import {formatCurrency, formatDate} from '../../utils/intl';
import {PREMIUM_ROW, CONTAINER, LINK} from './styles';
import {Hr} from '../Hr';
import {CheckoutPageType} from '../../lib/content';
import {downloadQuotation} from '../../pages/Checkout/utils';
import {Redacted} from '../Redacted';

interface PriceItem {
  amount: Currency;
  label: string;
}

interface Props {
  content: CheckoutPageType['selected'];
  /**
   * Title of selected plan to display at the top of the Sidebar
   */
  planTitle: string;

  limit: Currency | null;
  deductible: Currency | null;
  effectiveDate: string;
  endDate: string;
  quoteDocumentUuid?: string | null;
  quoteDocumentName: string | null;
  sessionId: string;

  /**
   * URL of the choose a plan step
   */
  changePlanLink: string;

  total: Currency | null;
  priceBreakdown: PriceItem[];
}

export const Sidebar = ({
  content,
  planTitle,
  limit,
  deductible,
  effectiveDate,
  endDate,
  quoteDocumentUuid,
  quoteDocumentName,
  changePlanLink,
  total,
  sessionId,
  priceBreakdown,
}: Props) => {
  const {css} = useFela();
  const [onKeyUp, onKeyDown] = useA11yKeyEvents();
  const [loading, setLoading] = React.useState(false);

  return (
    <div className={css(CONTAINER)}>
      <Spacing vertical="32" horizontal="24">
        <Redacted>
          <Typography
            className="fg-title body2"
            weight="semibold"
            variant="bodyLarge"
            color="black"
          >
            {planTitle}
          </Typography>
        </Redacted>

        <Spacing bottom="32" />

        <Typography className="fg-title body3" weight="semibold" color="black">
          {content.heading}
        </Typography>

        <Spacing bottom="32">
          {!!limit && (
            <Typography fill className="body3 fg-body">
              {content.limit.replace(
                '{limit}',
                formatCurrency(limit.amount / 100, {
                  currency: limit.code,
                  compact: true,
                }),
              )}
            </Typography>
          )}

          {!!deductible && (
            <Typography fill className="body3 fg-body">
              {content.deductible.replace(
                '{retention}',
                formatCurrency(deductible.amount / 100, {
                  currency: 'USD',
                }),
              )}
            </Typography>
          )}

          <Typography fill className="body3 fg-body">
            {content.effectiveDate
              .replace(
                '{startDate}',
                formatDate(new Date(effectiveDate), {
                  timeZone: 'UTC',
                  month: 'long',
                  day: 'numeric',
                  year: 'numeric',
                }),
              )
              .replace(
                '{endDate}',
                formatDate(new Date(endDate), {
                  timeZone: 'UTC',
                  month: 'long',
                  day: 'numeric',
                  year: 'numeric',
                }),
              )}
          </Typography>
        </Spacing>
        {quoteDocumentUuid && quoteDocumentName && (
          <Spacing bottom="8">
            <LinkButton
              onKeyDown={onKeyDown}
              onKeyUp={onKeyUp}
              className={`fg-primary ${css({display: 'flex'})}`}
              onClick={() => {
                setLoading(true);

                downloadQuotation(
                  quoteDocumentUuid,
                  quoteDocumentName,
                  sessionId,
                  () => setLoading(false),
                );
              }}
            >
              <DownloadIcon
                className="fg-primary"
                size={16}
                color={colors.blue500}
                stroke={colors.blue500}
                style={{marginRight: '4px'}}
              />

              <div>{content.downloadQuote}</div>

              <Spacing right="24" />

              {loading && <Spinner size={20} color="blue500" />}
            </LinkButton>
          </Spacing>
        )}
        <Spacing bottom="24">
          <a className={css(LINK)} href={changePlanLink}>
            <PencilIcon
              className="fg-primary"
              size={16}
              color={colors.blue500}
              stroke={colors.blue500}
              style={{marginRight: '4px'}}
            />

            <Typography
              className="fg-primary"
              color="blue500"
              weight="semibold"
            >
              {content.changePlan}
            </Typography>
          </a>
        </Spacing>

        <Hr />

        {!!priceBreakdown &&
          priceBreakdown.map((priceItem: PriceItem) => (
            <Fragment key={priceItem.label}>
              <Spacing bottom="16" />

              <div className={css(PREMIUM_ROW)}>
                <Typography className="body4 fg-body" variant="bodySmall">
                  {priceItem.label}
                </Typography>

                <Typography className="body4 fg-body" variant="bodySmall">
                  {formatCurrency(priceItem.amount.amount / 100, {
                    currency: priceItem.amount.code,
                    fractionDigits: 2,
                  })}
                </Typography>
              </div>

              <Spacing bottom="16" />

              <Hr />
            </Fragment>
          ))}

        <Spacing top="16">
          <div className={css(PREMIUM_ROW)}>
            <Typography
              className="body2 fg-title"
              weight="semibold"
              color="black"
              variant="bodyLarge"
            >
              {content.total}
            </Typography>

            {!!total && (
              <Typography
                className="body2 fg-title"
                weight="semibold"
                color="black"
                variant="bodyLarge"
              >
                {formatCurrency(total.amount / 100, {
                  currency: total.code,
                  fractionDigits: 2,
                })}
              </Typography>
            )}
          </div>
        </Spacing>

        <Typography
          className="body5 fg-body"
          fill
          color="black"
          variant="bodyXSmall"
          style={{textAlign: 'right'}}
        >
          {content.footer}
        </Typography>
        {!!content.disclaimer && (
          <>
            <Spacing top="16">
              <Typography
                className="body5 fg-body"
                fill
                color="black"
                variant="bodySmall"
                weight="semibold"
                style={{textAlign: 'center'}}
              >
                {content.disclaimer}
              </Typography>
            </Spacing>
          </>
        )}
      </Spacing>
    </div>
  );
};

Sidebar.displayName = 'Sidebar';
