import * as React from 'react';
import {LDContext, LDOptions} from 'launchdarkly-js-client-sdk';
import {LaunchDarklyContext} from './LaunchDarklyContext';
import {useLaunchDarklyInitialize} from './useLaunchDarklyInitialize';

interface Props {
  clientId: string;
  children: React.ReactNode;
}

export function LaunchDarkly({children, clientId}: Props) {
  const anonymousKeyRef = React.useRef<string>(
    `anonymous-${Date.now()}-${Math.random()}`,
  );

  const user: LDContext = React.useMemo(
    () => ({
      kind: 'user',
      anonymous: true,
      key: anonymousKeyRef.current,
    }),
    [],
  );

  const options: LDOptions = React.useMemo(
    () => ({
      useReport: true,
      allAttributesPrivate: true,
    }),
    [],
  );

  const ldClient = useLaunchDarklyInitialize(clientId, user, options);

  return (
    <LaunchDarklyContext.Provider value={ldClient}>
      {children}
    </LaunchDarklyContext.Provider>
  );
}
