import axios, {AxiosError} from 'axios';
import {createClient} from '/lib/api';
import {APIExceptionError} from '/lib/exceptions';

export let affinityReferrerUUID: string | null = null;
let partnerSlug: string = '';
let programSlug: string = '';

export const setAffinityReferrerUuid = (value: string) => {
  affinityReferrerUUID = value;
};

/**
 * useAffinityReferrerIdPromise
 * Fetches the referrer uuid from the Affinity-Customer-API-Gateway, based off the provided partner/program and session.
 */
export const useAffinityReferrerIdPromise = async (
  partner: string,
  program: string,
) => {
  // No need to make the request, if we already have the referrer for this partner/program
  if (programSlug === program && partnerSlug === partner) {
    return affinityReferrerUUID ?? '';
  }

  partnerSlug = partner;
  programSlug = program;

  // Since the affinity_referrer route is not part of a session (not part of a chain of customer-api request initiated
  // by creating a new policy) there is no reason to use the session framework. So, for this request we just use a
  // temp client with an empty auth, since auth is generated after a policy is made through customer-api.
  const client = createClient('');

  try {
    const response = await client.getAffinityReferrer(partner, program);

    if (!response.ok) {
      // If someone types a wrong address in the general partner-program form we don't want to make an Affinity alert,
      // and make a Sentry Alert about it. So we return an empty string. This results in the same flow as though
      // someone tried to gather a non-existent page from the _config in the previous flow.
      if (response.status === 404) {
        return '';
      }
      throw new APIExceptionError('getPartnerProgram');
    }

    return String(response.data);
  } catch (error: unknown) {
    // Re-throw APIExceptionError as-is to preserve the original error message
    if (error instanceof APIExceptionError) {
      throw error;
    }

    // Check for axios-specific errors to diagnose intermittent failures
    let errorDetails = '';

    if (axios.isAxiosError(error)) {
      const axiosError = error as AxiosError;
      if (axiosError.code === 'ECONNABORTED') {
        errorDetails = `Request timeout - partner: ${partner}, program: ${program}`;
      } else if (axiosError.code === 'ERR_CANCELED') {
        errorDetails = `Request was cancelled - partner: ${partner}, program: ${program}`;
      } else if (!axiosError.response) {
        errorDetails = `Network error - no response received - partner: ${partner}, program: ${program}, message: ${axiosError.message}`;
      } else {
        errorDetails = `Axios error: ${
          axiosError.code ?? 'unknown code'
        } - partner: ${partner}, program: ${program}, message: ${
          axiosError.message
        }`;
      }
    } else {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      errorDetails = `Non-axios error - partner: ${partner}, program: ${program}, error: ${errorMessage}`;
    }

    throw new APIExceptionError(`getAffinityReferrer - ${errorDetails}`);
  }
};
