import React from 'react';
import {useFela} from 'react-fela';

import {Typography as T} from '@crucible-risk/typography';
import {Flex} from '@crucible-risk/flex';
import {Spacing} from '@crucible-risk/spacing';
import {Button} from '@crucible-risk/button';
import {Configuration} from '@crucible-risk/sku-api-schema';

import {formatCurrency} from '../../utils/intl';
import {SelectPlanPageType} from '../../lib/content';

import {CARD, CARD_HEADER, CENTER_CARD, RECOMMENDED} from './styles';

export interface PlanCardProps {
  configuration: Configuration;
  content: SelectPlanPageType['card'];
  isRecommended?: boolean;
  onSelect: () => void;
  selectedId?: number;
  submitting?: boolean;
  submittingId?: number;
}

const adjustMillions = (str: string) => str.replace('M', ' Million');

export const PlanCard = ({
  configuration,
  content,
  isRecommended,
  onSelect,
  submitting,
  selectedId,
  submittingId,
}: PlanCardProps) => {
  const {css} = useFela({
    isSelected: selectedId === configuration.id,
    isRecommended,
  });

  return (
    <>
      <div className={css(CARD)}>
        <div className={css(CENTER_CARD)}>
          {isRecommended && (
            <div className={css(RECOMMENDED)}>
              <Spacing vertical="8" horizontal="16">
                <T
                  className="body4"
                  variant="bodySmall"
                  weight="semibold"
                  color="green600"
                  fill
                  align="center"
                  transform="uppercase"
                >
                  Recommended
                </T>
                <T
                  className="body5"
                  variant="bodyXSmall"
                  color="green600"
                  fill
                  align="center"
                  weight="semibold"
                >
                  based on your revenue, size, and detected risk{' '}
                </T>
              </Spacing>
            </div>
          )}

          <div className={css(CARD_HEADER)}>
            <Flex col align="center" fill>
              <T
                className="body2 fg-title"
                variant="bodyLarge"
                weight="semibold"
                align="center"
                color="black"
              >
                {content.body}
              </T>

              <Spacing bottom="8" />

              <T
                className="h1 fg-title"
                variant="displayRegular"
                weight="semibold"
                align="center"
                color="black"
              >
                {adjustMillions(
                  formatCurrency(configuration.limit.amount / 100, {
                    currency: configuration.limit.code,
                    compact: true,
                  }),
                )}
              </T>
            </Flex>

            <Spacing bottom="24" />
          </div>

          <Flex col align="center" fill>
            <T
              className="body5 fg-body"
              variant="bodyXSmall"
              align="center"
              weight="semibold"
              color="coolGray400"
            >
              {content.pricePrefix}
            </T>

            <T
              className="h2 fg-title"
              variant="displaySmall"
              align="center"
              weight="semibold"
              color="black"
            >
              {formatCurrency(configuration.premium.amount / 100, {
                currency: configuration.premium.code,
              })}
            </T>
            <Spacing bottom="16" />

            <Button
              className="fg-inverted bg-primary"
              label={content.button}
              onClick={onSelect}
              loading={submitting && submittingId === configuration.id}
              disabled={submitting && submittingId !== configuration.id}
              sharpCorners
            />

            <Spacing bottom="16" />

            <T
              className="body5 fg-body"
              variant="bodyXSmall"
              align="center"
              color="coolGray400"
            >
              {content.footer}
            </T>

            <Spacing bottom="32" />
          </Flex>

          {isRecommended && <Spacing height="8" />}
        </div>
      </div>
    </>
  );
};

PlanCard.displayName = 'PlanCard';
