import React from 'react';
import {useFela} from 'react-fela';

import {
  usePopover,
  RectShape,
  LayoutResult,
  PopoverController,
} from '@crucible-risk/popover-hook';
import {useCombineRefs} from '@crucible-risk/combine-refs-hook';
import {useFocusScope} from '@crucible-risk/focus-scope-hook';

import {
  containerStyle,
  backgroundStyle,
  borderStyle,
  contentStyle,
} from './dropdown.fela';

export type DropdownRef = PopoverController;

interface Props extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * If `true`, the modal dropdown is open.
   */
  open?: boolean;

  /**
   * Include a 24px margin around the dropdown content.
   */
  padded?: boolean;

  /**
   * When true, the dropdown backdrop will extend to cover the area of the target
   * element.
   */
  extend?: boolean;

  /**
   * When true, the dropdown width will be set to match the target element
   * width.
   */
  matchTargetWidth?: boolean;

  /**
   * Control the behavior of the dropdown when it is forced to be positioned
   * outside the edge of the viewport or boundary container in extreme
   * conditions.
   *
   * The default `overflow` mode will keep the dropdown attached to its target
   * and allows it to extend outside the boundary container.
   *
   * The `overlap` mode prevents the dropdown from overflowing the boundary
   * container and allows it to overlap its target.
   *
   * The `resize` mode prevents both overflow and overlap by resizing the
   * dropdown to fit within the available space.
   *
   * @default "overflow"
   */
  boundaryMode?: 'resize' | 'overflow' | 'overlap';

  /**
   * Optional callback to customize the measurement of the content DOM element.
   * The default behavior is to return `element.getBoundingClientRect()`.
   */
  getContentRect?: (element: HTMLElement) => RectShape;

  /**
   * Optional callback to customize the measurement of the target DOM element.
   * The default behavior is to return `element.getBoundingClientRect()`.
   */
  getTargetRect?: (element: HTMLElement) => RectShape;

  /**
   * Layout updated callback. Called with a `LayoutResult` object whenever the
   * position of the dropdown content changes.
   */
  onLayoutResult?: (result: LayoutResult | null) => void;

  /**
   * When set to `true` the focus scope will automatically focus the first
   * tabbable child element when activated.
   *
   * Optionally provide a function which returns an html element to receive
   * focus.
   */
  setFocus?: boolean | ((element: HTMLElement) => HTMLElement | null);

  /**
   * Prevent mouse and keyboard events from propagating outside of the focus
   * scope element.
   */
  cancelEvents?: boolean;

  /**
   * Close callback. Called when the user clicks or focuses outside the dropdown
   * element, or presses the esc key.
   */
  onClose?: (
    event: MouseEvent | FocusEvent | TouchEvent | KeyboardEvent,
    reason: 'key' | 'pointer' | 'focus',
  ) => void;

  /**
   * Prevent focus from leaving the dropdown element. When set, focus events
   * targeting elements outside the dropdown element will be redirected within,
   * tab focus navigation will cycle within the dropdown element, and click
   * event default behavior outside the dropdown element will be prevented.
   */
  trapFocus?: boolean;
}

export const DropdownRefComponent = (
  props: Props,
  ref: React.Ref<DropdownRef>,
) => {
  const {
    open = false,
    setFocus,
    cancelEvents,
    onClose,
    trapFocus,
    padded,
    children,
    getContentRect,
    getTargetRect,
    onLayoutResult,
    extend = false,
    boundaryMode = 'overflow',
    matchTargetWidth,
    style,
    ...rest
  } = props;

  const [layoutResult, setLayoutResult] = React.useState<LayoutResult | null>(
    null,
  );

  const popover = usePopover(
    {
      // Allow the dropdown above or below the target only.
      enableLeft: false,
      enableRight: false,

      // Prioritize positioning the dropdown below the target.
      region: 'bottom',

      // Horizontally snap the content to the left or right edge of the target,
      // (the default value also snaps to the center).
      snapTop: [0, 1],
      snapBottom: [0, 1],

      matchTargetWidth,

      constrainTop: boundaryMode === 'overlap',
      constrainBottom: boundaryMode === 'overlap',

      // Maintain the current resolved position if possible. The default behavior
      // when this is disabled is to always resolve the "best" position,
      // regardless of the current layout result.
      sticky: true,

      getContentRect,
      getTargetRect,
    },
    (result) => {
      setLayoutResult(result);

      if (onLayoutResult) {
        onLayoutResult(result);
      }
    },
  );

  React.useImperativeHandle(ref, () => popover, [popover]);

  const focusScopeActive = !!layoutResult;

  const focusScopeRef = useFocusScope(
    {
      onClose,
      trapFocus,
      setFocus,
      cancelEvents,
    },
    focusScopeActive,
  );

  const {css} = useFela({padded, region: layoutResult?.region});

  const combinedRef = useCombineRefs(focusScopeRef, popover.setContent);

  if (!open) {
    return null;
  }

  const extendStyle = {
    top:
      extend && layoutResult?.region === 'bottom'
        ? -layoutResult.target.height
        : undefined,
    right:
      extend && layoutResult?.region === 'left'
        ? -layoutResult.target.width
        : undefined,
    bottom:
      extend && layoutResult?.region === 'top'
        ? -layoutResult.target.height
        : undefined,
    left:
      extend && layoutResult?.region === 'right'
        ? -layoutResult.target.width
        : undefined,
  };

  return (
    <div
      ref={combinedRef}
      {...rest}
      style={{
        maxHeight:
          boundaryMode === 'resize'
            ? layoutResult?.region === 'bottom'
              ? layoutResult.bounds.bottom - layoutResult.content.top
              : layoutResult?.region === 'top'
              ? layoutResult.content.bottom - layoutResult.bounds.top
              : undefined
            : undefined,
        ...style,
      }}
      className={css(containerStyle)}
    >
      <div className={css(backgroundStyle)} style={extendStyle} />
      <div className={css(contentStyle)}>{children}</div>
      <div className={css(borderStyle)} style={extendStyle} />
    </div>
  );
};

export const Dropdown = React.forwardRef(DropdownRefComponent);

export type DropdownAttributes = JSX.LibraryManagedAttributes<
  typeof Dropdown,
  Props
>;
