import * as React from 'react';
import {Link} from 'react-router-dom';
import {Container} from '/component/container';
import {Typography as T} from '@crucible-risk/typography';
import {AnchorButton} from '@crucible-risk/button';
import {Flex} from '@crucible-risk/flex';
import {Spacing} from '@crucible-risk/spacing';

import {Markdown} from '/components/Markdown';
import {ContentPanel} from '../../ContentPanel';
import {Responsive} from '../../Responsive';
import {
  LandingPageAdditionalValue,
  LandingPageType,
  LandingPageValueProps,
} from '/lib/content';
import {
  BLACK_SECTION,
  CENTER_TEXT,
  GREY_SECTION,
  SECTION,
} from '/components/pages/ProgramLanding/styles';
import {useFela} from 'react-fela';
import {VALUE_TITLE_WIDTH} from '/components/ContentPanel/styles';
import {Static} from 'runtypes';
import {ReactElement} from 'react';
import {TitleHighlight} from '../../TextHighlight/titleHighlight';

interface ProgramLandingPageViewProps {
  content: LandingPageType;
  getStartedLink: string;
}

const WrappedAnchorButton = ({
  href,
  children,
}: {
  href: string;
  children: React.ReactNode;
}) => (
  <AnchorButton href={href} className="bg-primary fg-inverted" sharpCorners>
    {children}
  </AnchorButton>
);

export const ProgramLandingPageView = ({
  content,
  getStartedLink,
}: ProgramLandingPageViewProps) => {
  return (
    <>
      {GetMainSection(content, getStartedLink)}
      {GetStatsSection(content, getStartedLink)}
      {GetValuePropsSection(content.valueProps)}
      {GetAdditionalValueSection(content.additionalValue)}
      {GetAssetsSection(content)}
    </>
  );
};

function GetMainSection(
  content: LandingPageType,
  getStartedLink: string,
): ReactElement {
  return (
    <Container>
      <>
        <Spacing height="32" />
        <Flex align="center">
          <Flex col>
            <Spacing right="96" top="64">
              <T
                className="h1 fg-title"
                variant="displayRegular"
                weight="semibold"
                color="black"
              >
                {TitleHighlight({title: content.heading})}
              </T>
              <Spacing height="32" />
              <T className="body2 fg-body" variant="bodyLarge" color="bodyCopy">
                <Markdown markdown={content.body} />
              </T>
              <Spacing height="64" />
              <Link to={getStartedLink} component={WrappedAnchorButton}>
                {content.callToActionText}
              </Link>
            </Spacing>
          </Flex>

          <Responsive.Desktop>
            <Spacing right="16" left="16">
              <img
                src={content.image.url}
                alt="Industry Landing"
                style={{maxWidth: 440}}
              />
            </Spacing>
          </Responsive.Desktop>
        </Flex>
        <Spacing height="96" />
      </>
    </Container>
  );
}

function GetStatsSection(
  content: LandingPageType,
  getStartedLink: string,
): ReactElement {
  const {css} = useFela();
  return (
    <div className={css(GREY_SECTION)}>
      <Spacing height="64" />
      <Container>
        {content.introStats && (
          <ContentPanel>
            <ContentPanel.RowNItems
              content={content.introStats.map((introStat) => {
                return (
                  <ContentPanel.GeneralizedItem
                    key={introStat.title}
                    icon={<img width="60px" src={introStat.icon?.url} alt="" />}
                    title={
                      <T color="activeBlue" variant="displaySmall">
                        {introStat.title ? introStat.title : ''}
                      </T>
                    }
                    description={
                      <T color="black" variant="bodyLarge">
                        {introStat.bodyText ? introStat.bodyText : ''}
                      </T>
                    }
                  />
                );
              })}
            />
          </ContentPanel>
        )}
        <Spacing height="32" />
        <div className={css(CENTER_TEXT)}>
          <Link to={getStartedLink} component={WrappedAnchorButton}>
            {content.callToActionText}
          </Link>
        </div>
      </Container>
      <Spacing height="64" />
    </div>
  );
}

function GetValuePropsSection(
  sectionData: Static<typeof LandingPageValueProps> | undefined,
): ReactElement {
  const {css} = useFela();
  return (
    <>
      {sectionData && (
        <div className={css(BLACK_SECTION)}>
          <Container>
            <ContentPanel>
              <ContentPanel.RowNItems
                content={[
                  <ContentPanel.GeneralizedItem
                    key={sectionData.title}
                    title={
                      <T
                        color="white"
                        variant="displayRegular"
                        weight="semibold"
                      >
                        {sectionData.title}
                      </T>
                    }
                  />,
                  <>
                    {sectionData.subsections?.map((infoBlock) => {
                      return (
                        <div key={infoBlock.title}>
                          <ContentPanel.GeneralizedItem
                            title={
                              <T
                                color="white"
                                variant="bodyLarge"
                                weight="semibold"
                              >
                                {infoBlock.title}
                              </T>
                            }
                            description={
                              <T color="lightGrey" variant="bodyRegular">
                                {infoBlock.bodyText}
                              </T>
                            }
                          />
                          <Spacing height="32" />
                        </div>
                      );
                    })}
                  </>,
                ]}
              />
            </ContentPanel>
          </Container>
        </div>
      )}
    </>
  );
}

function GetAdditionalValueSection(
  sectionData: Static<typeof LandingPageAdditionalValue> | undefined,
): JSX.Element {
  const {css} = useFela();
  return (
    <>
      {sectionData && (
        <div className={css(SECTION)}>
          <Container>
            <ContentPanel.GeneralizedItem
              title={
                <div className={css(VALUE_TITLE_WIDTH)}>
                  <T color="black" variant="displayRegular" weight="semibold">
                    {sectionData.title?.title}
                  </T>
                </div>
              }
              title_spacing="32"
              description={
                <div className={css(VALUE_TITLE_WIDTH)}>
                  <T color="bodyCopy" variant="bodyLarge" align="center">
                    {sectionData.title?.bodyText}
                  </T>
                </div>
              }
            />
          </Container>
          <Spacing height="64" />
          <Container>
            {sectionData.subsections && (
              <ContentPanel>
                <ContentPanel.RowNItems
                  content={sectionData.subsections?.map((infoBlock) => {
                    return (
                      <ContentPanel.GeneralizedItem
                        key={infoBlock.title}
                        icon={
                          <img width="60px" src={infoBlock.icon?.url} alt="" />
                        }
                        icon_spacing="32"
                        title={
                          <T
                            color="black"
                            variant="displayXSmall"
                            weight="semibold"
                          >
                            {infoBlock.title}
                          </T>
                        }
                        title_spacing="16"
                        description={
                          <T color="bodyCopy" variant="bodyLarge">
                            {infoBlock.bodyText}
                          </T>
                        }
                      />
                    );
                  })}
                />
              </ContentPanel>
            )}
          </Container>
        </div>
      )}
    </>
  );
}

function GetAssetsSection(content: LandingPageType): ReactElement {
  const {css} = useFela();
  return (
    <div className={css(GREY_SECTION)}>
      <Container>
        {content.linkCards && (
          <>
            <Spacing height="56" />
            <ContentPanel>
              <ContentPanel.Row3Items
                content={content.linkCards.map((linkCard) => (
                  <ContentPanel.LinkCard
                    key={linkCard.superText}
                    linkHref={
                      linkCard.linkHref || linkCard.linkAsset?.url || '#'
                    }
                    linkIcon={linkCard.linkIcon}
                    linkText={linkCard.linkText}
                    mainText={linkCard.mainText}
                    superText={linkCard.superText}
                  />
                ))}
              />
            </ContentPanel>
          </>
        )}
      </Container>
    </div>
  );
}
