/* eslint-disable eslint-comments/no-restricted-disable */

import {AffinitySession} from '../types/AffinitySession';

interface HasAffinityReferrerUuid {
  readonly affinity_referrer_uuid: unknown;
}

interface HasAffinityReferrerUuidString {
  readonly affinity_referrer_uuid: string;
}

interface HasInsurancePolicyUuid {
  readonly insurance_policy_uuid: unknown;
}

interface HasInsurancePolicyUuidString {
  readonly insurance_policy_uuid: string;
}

function filterByHasAffinityReferrerUuid(
  session: object,
): session is HasAffinityReferrerUuid {
  return Object.prototype.hasOwnProperty.call(
    session,
    'affinity_referrer_uuid',
  );
}

function filterByHasAffinityReferrerUuidString(
  session: HasAffinityReferrerUuid,
): session is HasAffinityReferrerUuidString {
  return typeof session.affinity_referrer_uuid === 'string';
}

function filterByHasInsurancePolicyUuid(
  session: object,
): session is HasInsurancePolicyUuid {
  return Object.prototype.hasOwnProperty.call(session, 'insurance_policy_uuid');
}

function filterByHasInsurancePolicyUuidString(
  session: HasInsurancePolicyUuid,
): session is HasInsurancePolicyUuidString {
  return typeof session.insurance_policy_uuid === 'string';
}

export function validateAffinitySession(session: object): AffinitySession {
  if (
    !filterByHasAffinityReferrerUuid(session) ||
    typeof session.affinity_referrer_uuid === 'undefined'
  ) {
    throw new Error('Affinity referrer is missing.');
  }

  if (
    !filterByHasInsurancePolicyUuid(session) ||
    typeof session.insurance_policy_uuid === 'undefined'
  ) {
    throw new Error('Insurance policy is missing.');
  }

  if (!filterByHasAffinityReferrerUuidString(session)) {
    throw new Error(
      `The Affinity referrer is not a valid ID: ${JSON.stringify(
        session.affinity_referrer_uuid,
      )}`,
    );
  }

  if (!filterByHasInsurancePolicyUuidString(session)) {
    throw new Error(
      `The insurance policy is not a valid ID: ${JSON.stringify(
        session.insurance_policy_uuid,
      )}`,
    );
  }

  return session;
}
