import {RC} from '@crucible-risk/fela-renderer';

export const flexStyle: RC<{col: boolean; fill: boolean; wrap: boolean}> = ({
  col,
  fill,
  wrap,
}) => ({
  display: 'flex',
  flexDirection: col ? 'column' : 'row',
  flexGrow: fill ? 1 : undefined,
  flexWrap: wrap ? 'wrap' : 'nowrap',
});

export const alignStyle: RC<{
  align: 'start' | 'center' | 'end' | 'stretch';
}> = ({align}) => ({
  alignItems:
    align === 'start'
      ? 'flex-start'
      : align === 'end'
      ? 'flex-end'
      : align === 'center'
      ? 'center'
      : align === 'stretch'
      ? 'stretch'
      : undefined,
});

export const justifyStyle: RC<{
  justify: 'start' | 'center' | 'end' | 'stretch' | 'between';
}> = ({justify}) => ({
  justifyContent:
    justify === 'start'
      ? 'flex-start'
      : justify === 'end'
      ? 'flex-end'
      : justify === 'center'
      ? 'center'
      : justify === 'stretch'
      ? 'stretch'
      : justify === 'between'
      ? 'space-between'
      : undefined,
});
