import React, {Fragment} from 'react';
import {useFela} from 'react-fela';

import {Spinner} from '@crucible-risk/spinner';
import {Select, Option} from '@crucible-risk/select';

import {ChangeFunction, Question} from './ApplicationQuestions';
import {QuestionInputSet} from './EditView';
import {Hr} from '../Hr';
import {childQuestions} from './child-questions';
import {INPUT_ROW, INPUT_COLUMN} from './styles';

interface SelectQuestionProps {
  disabled: boolean;
  question: Question;
  onChange: ChangeFunction;
  questionInfo: Record<string, string>;
  companyName: string;
  active: boolean;
}

export const SelectQuestion: React.FC<SelectQuestionProps> = ({
  disabled,
  question,
  onChange,
  questionInfo,
  companyName,
  active,
}) => {
  const {css} = useFela();
  if (!question.answer_options) {
    return null;
  }

  /**
   * An answer is valid if question.answer_text matches an option in question.answer_options
   */
  const isValidAnswer =
    question.answer_options &&
    question.answer_options.some(
      (answerOption) => answerOption.value === question.answer_text,
    );

  return (
    <Fragment key={question.id}>
      {/* Child Questions are indented and dont need an HR */}
      {!childQuestions[question.id] && <Hr />}

      <QuestionInputSet
        companyName={companyName}
        questionInfo={questionInfo}
        question={question}
        inputs={
          <div className={css(INPUT_ROW)}>
            <div className={css(INPUT_COLUMN)} style={{flexGrow: 1}}>
              <Select
                intent={
                  question.required && !question.answer_text
                    ? 'danger'
                    : 'neutral'
                }
                size="small"
                fill
                disabled={disabled}
                value={
                  isValidAnswer
                    ? String(question.answer_text)
                    : question.answer_options[
                        question.answer_options.length - 1
                      ].value
                }
                aria-label={question.question_text}
                onChange={(value) => {
                  onChange(question, value);
                }}
              >
                {question.answer_options &&
                  question.answer_options.map(
                    (option: {label: string; value: string}) => (
                      <Option
                        key={option.value}
                        value={option.value}
                        label={option.label}
                      />
                    ),
                  )}
              </Select>
            </div>
            <div
              className={css(INPUT_COLUMN)}
              style={{alignSelf: 'center', minWidth: 16}}
            >
              {active && <Spinner size={0} />}
            </div>
          </div>
        }
      />
    </Fragment>
  );
};

SelectQuestion.displayName = 'SelectQuestion';
