import * as React from 'react';

/**
 * This is the new createPortal used in Broker Dashboard. Moving this into the component library is on
 * customer tool's list. Once that is done, we should be able to remove this and use the component library
 * version instead.
 */

export interface ContainerContextValue<T> {
  /**
   * True to skip `useLayoutEffect` and invoke the state update immediately.
   * This is almost exclusively useful in server and testing environments where
   * you have a custom state provider.
   */
  immediate: boolean;

  /**
   * Set a value in portal. This is how new components are added.
   */
  setValue: (_id: string, _element: T) => void;

  /**
   * Remove a value from portal. This is how old components are removed.
   */
  unsetValue: (_id: string) => void;
}

export interface ProviderProps<T> {
  /**
   * Whatever children need access to portal context.
   */
  children?: React.ReactNode;
}

export interface Portal<T> {
  /**
   * Outermost wrapper component that needs to be provided to pass portal
   * state around the React tree.
   */
  Provider: React.ComponentType<ProviderProps<T>>;

  /**
   * Put a new value with the given id into portal and remove it when
   * your component is unmounted. Doing so will trigger updates on any component
   * consuming portal state.
   *
   * NOTE: This is a hook and comes with all the restrictions and caveats that
   * all hooks have.
   */
  useBinding: (id: string, value: T, dependents?: unknown[]) => null;

  /**
   * Get all the values that have been put into portal. Your component
   * will re-render when a new child is added/removed from portal.
   *
   * NOTE: This is a hook and comes with all the restrictions and caveats that
   * all hooks have.
   */
  useValues: () => ValueMap<T>;

  /**
   * Access a "setter" so that you can non-structurally inject values into
   * portal. This is useful for things that are more transient, e.g. pushing
   * toasts.
   */
  useSetValue: () => ContainerContextValue<T>['setValue'];

  /**
   * Access an "unsetter" so that you can non-structurally remove values from
   * portal. This is useful for removing things that were injected with the
   * aforementioned `useSetValue`.
   */
  useUnsetValue: () => ContainerContextValue<T>['unsetValue'];
}

/**
 * Shape of the data stored in portal.
 * Normally T is of type `React.ReactElement`, but you can use whatever you'd like.
 */
export interface ValueMap<T> {
  [key: string]: T;
}

type TContainerContext<T> = React.Context<ContainerContextValue<T> | null>;
type TValueContext<T> = React.Context<ValueMap<T>>;

export const createPortal = function createPortal<T>(): Portal<T> {
  /**
   * The container context is used to store metadata that's applicable to
   * all instances of the `Portal`. This includes methods for getting/setting
   * values and configuration for things like `immediate`.
   */
  const ContainerContext: TContainerContext<T> = React.createContext(
    null as ContainerContextValue<T> | null,
  );

  /**
   * The value context is used to store the values in portal set by the
   * user. This context is separate from the container context in order to
   * avoid unecessary state updates (`ContainerContext` should never trigger
   * a re-render) and in order to prevent users access to internal machinery.
   */
  const ValueContext: TValueContext<T> = React.createContext({});

  const useContainer = (): ContainerContextValue<T> => {
    const contextValue = React.useContext(ContainerContext);
    if (!contextValue) {
      throw new Error('Portal component is not wrapped in `Portal.Provider`.');
    }
    return contextValue;
  };

  const useBinding = (id: string, value: T): null => {
    const {setValue, unsetValue, immediate} = useContainer();

    // `useLayoutEffect` is here to block browser paint so that we can update
    // the React tree and avoid FOUC.
    React.useLayoutEffect((): (() => void) => {
      setValue(id, value);
      return (): void => {
        unsetValue(id);
      };
    }, [setValue, unsetValue, id, value]);

    // `immediate` mode triggers the state update on render. Normally this is
    // not desirable because updates on render are a no-no, but during server
    // rendering this is valuable to capture what updates are happening.
    if (immediate) {
      setValue(id, value);
    }

    return null;
  };

  const useValues = (): ValueMap<T> => {
    return React.useContext(ValueContext);
  };

  const useSetValue = () => {
    return useContainer().setValue;
  };

  const useUnsetValue = () => {
    return useContainer().unsetValue;
  };

  const Provider = ({children}: ProviderProps<T>): React.ReactElement => {
    const [stateValues, setState] = React.useState({});
    const [container] = React.useState(() => {
      return {
        immediate: false,
        setValue: (id: string, value: T): void => {
          setState(
            (oldValues: ValueMap<T>): ValueMap<T> => {
              if (id in oldValues && oldValues[id] === value) {
                return oldValues;
              }
              return {
                ...oldValues,
                [id]: value,
              };
            },
          );
        },
        unsetValue: (id: string): void => {
          setState((values: ValueMap<T>): ValueMap<T> | null => {
            if (id in values) {
              const newValues = {...values};
              delete newValues[id];
              return newValues;
            }
            return values;
          });
        },
      };
    });

    return (
      <ContainerContext.Provider value={container}>
        <ValueContext.Provider value={stateValues}>
          {children}
        </ValueContext.Provider>
      </ContainerContext.Provider>
    );
  };

  return {
    Provider,
    useBinding,
    useValues,
    useSetValue,
    useUnsetValue,
  };
};
