import * as React from 'react';
import {SearchIndex} from 'algoliasearch';

import TextField from '@material-ui/core/TextField';
import Autocomplete from '@material-ui/lab/Autocomplete';
import Paper from '@material-ui/core/Paper';
import CircularProgress from '@material-ui/core/CircularProgress';

import {
  fontStacks,
  colors,
  formatTypeVariant,
  typeVariants,
} from '@crucible-risk/theme';

export interface AlgoliaHit {
  'categories.lvl0': string;
  gics: string;
  name: string;
  useGrossProfitNetRevenue: boolean;
  objectID: string;
  _highlightResult?: {
    name: {
      value: string;
    };
  };
}

interface Results {
  hits: AlgoliaHit[];
  facets?: Record<string, Record<string, number>>;
  queryID?: string;
}

const HIGHLIGHT_PRE_TAG = '!@#$%';
const HIGHLIGHT_POST_TAG = '%$#@!';

const searchOptions = {
  clickAnalytics: true,
  attributesToHighlight: ['name'],
  hitsPerPage: 15,
  highlightPreTag: HIGHLIGHT_PRE_TAG,
  highlightPostTag: HIGHLIGHT_POST_TAG,
  facets: ['categories.lvl0'],
};

interface IndustrySearchFieldProps {
  algolia: SearchIndex;
  industryName: string;
  placeholder: string;
  value?: string;
  onChange: Function;
  onBlur: Function;
  isError: boolean;
}

export const IndustrySearchField = (props: IndustrySearchFieldProps) => {
  const {algolia, isError, value, industryName, onChange, onBlur} = props;

  const [open, setOpen] = React.useState(false);
  const [inputValue, setInputValue] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [results, setResults] = React.useState<Results>();

  const handleChange = React.useCallback(
    (val: string) => {
      onChange(parseInt(val, 10));
    },
    [onChange],
  );

  React.useEffect(() => {
    setInputValue(industryName);
  }, [industryName]);

  React.useEffect(() => {
    let active = true;
    setLoading(true);

    void algolia
      .search<AlgoliaHit>(inputValue, searchOptions)
      .then((results) => {
        if (active) {
          setResults(results);
          setLoading(false);
        }
      });

    return () => {
      active = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [inputValue, setResults]);

  const resultMap = React.useMemo(() => {
    const map: {[key: string]: AlgoliaHit} = {};

    for (const entry of results?.hits ?? []) {
      map[entry.objectID] = entry;
    }

    return map;
  }, [results]);

  const sortedHits = React.useMemo(() => {
    const categoryMap: {[key: string]: number} = {};
    const indexMap: {[key: string]: number} = {};
    let lastCategoryIndex = 0;
    let lastIndex = 0;
    for (const hit of results?.hits ?? []) {
      const category = hit['categories.lvl0'];
      indexMap[hit.objectID] = ++lastIndex;
      if (!(category in categoryMap)) {
        categoryMap[category] = ++lastCategoryIndex;
      }
    }
    const hits = results?.hits ?? [];
    return hits.slice().sort((a, b) => {
      const f1 =
        categoryMap[a['categories.lvl0']] - categoryMap[b['categories.lvl0']];
      const f2 = indexMap[a.objectID] - indexMap[b.objectID];
      return f1 !== 0 ? f1 : f2;
    });
  }, [results]);

  return (
    <Autocomplete
      onBlur={React.useCallback(() => onBlur(), [onBlur])}
      onChange={React.useCallback(
        (_, val) => handleChange(val?.objectID ?? ''),
        [handleChange],
      )}
      inputValue={inputValue}
      onInputChange={React.useCallback((_, value) => setInputValue(value), [])}
      groupBy={React.useCallback((option) => option['categories.lvl0'], [])}
      fullWidth
      open={open && (value !== undefined ? resultMap[value] : null) !== null}
      onOpen={React.useCallback(() => setOpen(true), [])}
      onClose={React.useCallback(() => setOpen(false), [])}
      getOptionSelected={React.useCallback((option, value) => {
        return option.objectID === value.objectID;
      }, [])}
      getOptionLabel={React.useCallback(
        (option) => {
          if (
            Object.prototype.hasOwnProperty.call(resultMap, option.objectID)
          ) {
            return resultMap[option.objectID].name;
          }

          return '';
        },
        [resultMap],
      )}
      autoComplete
      clearOnBlur={false}
      includeInputInList
      filterOptions={React.useCallback((x) => x, [])}
      PaperComponent={React.useCallback(({children, ...rest}) => {
        return <Paper {...rest}>{children}</Paper>;
      }, [])}
      renderOption={React.useCallback((option: AlgoliaHit) => {
        if (option._highlightResult !== undefined) {
          const value = option._highlightResult.name.value;
          let lastIndex = 0;
          const chunks = [];

          while (true) {
            const startIndex = value.indexOf(HIGHLIGHT_PRE_TAG, lastIndex);
            if (startIndex === -1) {
              chunks.push({value: value.substring(lastIndex)});
              break;
            }
            const endIndex = value.indexOf(HIGHLIGHT_POST_TAG, startIndex);

            const key = `${startIndex}${endIndex}${option.objectID}`;

            chunks.push({
              key,
              value: value.substring(lastIndex, startIndex),
            });

            chunks.push({
              key: key + 'hl',
              type: 'highlight',
              value: value.substring(
                startIndex + HIGHLIGHT_PRE_TAG.length,
                endIndex,
              ),
            });
            lastIndex = endIndex + HIGHLIGHT_POST_TAG.length;
          }
          return (
            <div>
              {chunks.map((entry) => {
                if (entry.type === 'highlight') {
                  return (
                    <span key={entry.key} style={{fontWeight: 'bold'}}>
                      {entry.value}
                    </span>
                  );
                }
                return <span key={entry.key}>{entry.value}</span>;
              })}
            </div>
          );
        }
        return option.name;
      }, [])}
      options={sortedHits}
      loading={loading && results?.hits.length === 0}
      renderInput={React.useCallback(
        (params) => {
          return (
            <TextField
              {...params}
              variant="outlined"
              error={isError}
              placeholder="Start typing an industry..."
              InputProps={{
                ...params.InputProps,
                style: {
                  paddingLeft: 0,
                  paddingBottom: 0,
                  paddingTop: 0,
                  fontFamily: fontStacks.base.join(', '),
                  ...formatTypeVariant(typeVariants.bodySmall),
                  color: colors.bodyCopy,
                },
                endAdornment: (
                  <>
                    {loading ? (
                      <CircularProgress color="inherit" size={24} />
                    ) : null}
                    {params.InputProps.endAdornment}
                  </>
                ),
              }}
              inputProps={{
                ...params.inputProps,
                style: {
                  padding: '0 0 0 8px',
                  height: 32,
                },
              }}
            />
          );
        },
        [isError, loading],
      )}
    />
  );
};
