import * as React from 'react';
import {useFela} from 'react-fela';
import {SearchIndex} from 'algoliasearch';

import {Container} from '@crucible-risk/container';
import {Spacing} from '@crucible-risk/spacing';
import {AnchorButton, Button} from '@crucible-risk/button';
import {Typography as T} from '@crucible-risk/typography';
import {DownloadIcon} from '@crucible-risk/icon';
import {Flex} from '@crucible-risk/flex';

import {Steps} from '/components/Steps';
import {Responsive} from '/components/Responsive';
import {ContentPanel} from '/components/ContentPanel';
import {Markdown} from '/components/Markdown';
import {TitleHighlight} from '../../TextHighlight/titleHighlight';
import {CompanyDetails} from '/components/CompanyDetails';
import {Alert} from '/components/Alert';

import {
  AddressAutoCompleteService,
  AddressGeocoderService,
} from '/lib/geocoder';
import {GeneralInfoPageType} from '/lib/content';

import {
  GeneralInfoFormChangeHandler,
  GeneralInfoFormValues,
  GeneralInfoFormFlags,
  GeneralInfoFormBlurHandler,
  GeneralInfoValidationErrors,
} from '/hooks/useGeneralInfoForm';

interface GeneralInfoPageViewProps {
  algolia: SearchIndex;
  industryName?: string;
  data: GeneralInfoFormValues;
  onChange: GeneralInfoFormChangeHandler;
  onBlur: GeneralInfoFormBlurHandler;
  content: GeneralInfoPageType;
  formCompleted: boolean;
  formDirty: GeneralInfoFormFlags;
  formValid: GeneralInfoFormFlags;
  formErrors: GeneralInfoValidationErrors;
  onSubmit: () => void;
  submitting: boolean;
  error?: Error;
  onOpenContact: () => void;
  geocoder: {
    addressAutocompleteService: AddressAutoCompleteService;
    addressGeocoderService: AddressGeocoderService;
  };
  showGpnr?: boolean;
  showPrograms?: boolean;
  agencyProgramFlag?: boolean;
}

export const GeneralInfoPageView = ({
  algolia,
  industryName = '',
  data,
  onChange,
  onBlur,
  content,
  geocoder,
  formCompleted,
  formDirty,
  formValid,
  formErrors,
  onSubmit,
  submitting,
  error,
  onOpenContact,
  showGpnr = false,
  showPrograms = false,
  agencyProgramFlag = false,
}: GeneralInfoPageViewProps) => {
  const {css} = useFela();

  const [errorState, setErrorState] = React.useState<Error | undefined>(error);
  error = error !== undefined ? error : errorState;

  return (
    <Container>
      <>
        <Spacing top="56" bottom="56">
          <Steps>
            <Steps.Step title="General Info" status="active" />
            <Steps.Step title="Select a Plan" />
            <Steps.Step title="Confirmation" />
            <Steps.Step title="Checkout" />
          </Steps>
        </Spacing>
        <Alert error={error} onOpenContact={onOpenContact} />
        <Responsive reverse>
          <Responsive.Column>
            <Spacing right="16" left="16">
              <Spacing bottom="24">
                <T
                  className="fg-title h1"
                  variant="displaySmall"
                  weight="semibold"
                  color="black"
                >
                  {TitleHighlight({title: content.heading})}
                </T>
              </Spacing>
              <Spacing bottom="32">
                <T
                  className="fg-body body2"
                  variant="bodyLarge"
                  weight="medium"
                  color="bodyCopy"
                >
                  <Markdown markdown={content.subHeading} />
                </T>
              </Spacing>
              <Spacing bottom="32">
                <CompanyDetails
                  algolia={algolia}
                  industryName={industryName}
                  editing
                  labelStyle="stacked"
                  content={content.form}
                  dirty={formDirty}
                  valid={formValid}
                  validationErrors={formErrors}
                  values={data}
                  onChange={onChange}
                  onBlur={onBlur}
                  hideFields={[
                    ...((!showGpnr ? ['grossProfitNetRevenue'] : []) as Array<
                      keyof GeneralInfoFormValues
                    >),
                  ]}
                  geocoder={geocoder}
                  setErrorState={setErrorState}
                  showPrograms={showPrograms}
                  agencyProgramFlag={agencyProgramFlag}
                />
              </Spacing>
              <Button
                className="bg-primary fg-inverted"
                size="regular"
                disabled={!formCompleted}
                onClick={onSubmit}
                loading={submitting}
                sharpCorners
              >
                {content.button}
              </Button>
            </Spacing>
          </Responsive.Column>

          <Responsive.Column>
            <Spacing right="16" left="16">
              <Spacing bottom="24" />

              <Responsive.Desktop>
                <img
                  src={content.image.url}
                  alt="General Info Form"
                  className={css({
                    width: '435px',
                    display: 'block',
                    margin: 'auto',
                  })}
                />

                <Spacing bottom="32" />

                <Flex>
                  <div>
                    <div>
                      <T
                        variant="displaySmall"
                        weight="semibold"
                        color="red600"
                        align="center"
                        fill
                      >
                        {content.imageSubText.left.heading}
                      </T>
                    </div>
                    <div>
                      <Spacing horizontal="24">
                        <T
                          className="fg-body bodyXSmall"
                          variant="bodySmall"
                          align="center"
                          fill
                        >
                          <Markdown markdown={content.imageSubText.left.body} />
                        </T>
                      </Spacing>
                    </div>
                  </div>
                  <div>
                    <div>
                      <T
                        variant="displaySmall"
                        weight="semibold"
                        color="red600"
                        align="center"
                        fill
                      >
                        {content.imageSubText.right.heading}
                      </T>
                    </div>
                    <div>
                      <Spacing horizontal="24">
                        <T
                          className="fg-body bodyXSmall"
                          variant="bodySmall"
                          align="center"
                          fill
                        >
                          <Markdown
                            markdown={content.imageSubText.right.body}
                          />
                        </T>
                      </Spacing>
                    </div>
                  </div>
                </Flex>
              </Responsive.Desktop>
            </Spacing>
          </Responsive.Column>
        </Responsive>
        <Spacing top="48" bottom="48">
          {(!!content.body || !!content.features) && <ContentPanel.Divider />}{' '}
        </Spacing>
        {!!content.body && (
          <ContentPanel
            title={content.body.heading}
            description={content.body.body}
          />
        )}
        {!!content.features && (
          <>
            <Spacing top="48" bottom="48">
              <ContentPanel.Divider />
            </Spacing>
            <ContentPanel
              title={content.features.heading}
              footer={content.features.footer}
            >
              {content.features.left.map((left, index) => {
                const right = content.features?.right[index];
                return (
                  <ContentPanel.Row2Items
                    key={left.heading}
                    left={
                      <ContentPanel.Item2
                        title={left.heading}
                        description={left.body}
                      />
                    }
                    right={
                      <ContentPanel.Item2
                        title={right?.heading ?? ''}
                        description={right?.body ?? ''}
                      />
                    }
                  />
                );
              })}
            </ContentPanel>
            <Spacing bottom="48">
              <ContentPanel.Divider />
            </Spacing>
          </>
        )}
        <Spacing bottom="64">
          <ContentPanel.RowPrimary
            title={content.footer}
            legal={
              content.legal.href !== '#' ? (
                <AnchorButton
                  className="fg-secondary"
                  href={content.legal.href}
                  minimal
                  sharpCorners
                  size="small"
                  appendStart={<DownloadIcon />}
                  target="_blank"
                  rel="noopener noreferrer"
                  tight
                >
                  {content.legal.content}
                </AnchorButton>
              ) : undefined
            }
            claims={
              content.claims.href !== '#' ? (
                <AnchorButton
                  className="fg-secondary"
                  href={content.claims.href}
                  minimal
                  sharpCorners
                  size="small"
                  appendStart={<DownloadIcon />}
                  target="_blank"
                  rel="noopener noreferrer"
                  tight
                >
                  {content.claims.content}
                </AnchorButton>
              ) : undefined
            }
          />
        </Spacing>
      </>
    </Container>
  );
};
