import * as React from 'react';
import {useHistory} from 'react-router-dom';
import {Helmet} from 'react-helmet';

import {useProgram} from '/components/ContentProvider';
import {ConfirmationPageView} from '/components/pages/Confirmation';
import {AlgoliaHit} from '/components/IndustrySearchField';

import {withPreloadedDataPage} from '/lib/withPreloadedDataPage';
import {
  addressAutocompleteService,
  addressGeocoderService,
} from '/lib/geocoder';
import {initAlgolia} from '/lib/algolia';

import {confirmationPageDataLoader, ConfirmationPageProps} from './loader';
import {useConfirmationPageState} from './useConfirmationPageState';
import {UseSupportChat} from '/lib/chat';

const _ConfirmationPage: React.FC<ConfirmationPageProps> = (props) => {
  const {
    policy,
    applicationQuestions,
    sessionId,
    configuration: initialConfiguration,
  } = props;
  const history = useHistory();
  const programContent = useProgram();
  const agencyProgramFlag = programContent.agencyProgramFlag;
  const [state, actions] = useConfirmationPageState({
    sessionId: sessionId ?? '',
    initialConfiguration,
    insurancePolicy: policy,
    initialQuestions: applicationQuestions,
    agencyProgramFlag,
  });

  const [industry, setIndustry] = React.useState<AlgoliaHit>();
  const algolia = initAlgolia(programContent.algoliaIndustriesIndex);
  const industryID = state.generalInfo.values.industry;
  const objectID = !isNaN(industryID) ? industryID.toString() : '0';

  React.useEffect(() => {
    if (objectID !== '0') {
      algolia.getObject<AlgoliaHit>(objectID).then((result) => {
        setIndustry(result);
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [objectID]);

  const {show} = UseSupportChat();

  return (
    <>
      <Helmet>
        <title>
          {programContent.confirmationPage.pageTitle ??
            programContent.pageTitle}
        </title>
      </Helmet>
      <ConfirmationPageView
        algolia={algolia}
        industryName={industry?.name ?? ''}
        showGpnr={industry?.useGrossProfitNetRevenue ?? false}
        isSlow={state.quote.isSlow}
        error={state.applicationQuestions.error || state.quote.error}
        submitting={state.quote.inProgress}
        applicationQuestions={{
          activity: state.applicationQuestions.activity,
          submitting: state.applicationQuestions.busy,
          completed: state.applicationQuestions.complete,
          data: state.applicationQuestions.questions,
          onChange: actions.applicationQuestions.updateAnswer,
          onSave: (q) => void actions.applicationQuestions.saveQuestion(q),
        }}
        policy={
          state.configuration.configuration
            ? {
                name:
                  state.configuration.configuration.display_name ?? 'Unknown',
                limit: state.configuration.configuration.limit?.amount ?? 0,
                retention:
                  state.configuration.configuration.retention?.amount ?? 0,
                premium: state.configuration.configuration.premium?.amount ?? 0,
                onChange: () => {
                  history.push({
                    pathname: history.location.pathname.replace(
                      'confirmation',
                      'select-plan',
                    ),
                    search: history.location.search,
                  });
                },
              }
            : null
        }
        companyDetails={{
          data: state.generalInfo.values,
          completed: state.generalInfo.formIsValid,
          dirty: state.generalInfo.dirty,
          valid: state.generalInfo.valid,
          onChange: () => {},
          onBlur: () => {},
          validationErrors: state.generalInfo.validationErrors,
        }}
        content={programContent.confirmationPage}
        hasFTF={!!state.configuration.configuration?.base_configuration_id}
        onRemoveDualControl={actions.configuration.removeFTF}
        onContinue={() => {
          // Create quote
          actions.quote.issueQuote().then((quote) => {
            if (quote) {
              if (quote.lifecycle_state !== 'QUOTATION_ACTIVE') {
                // Not active, move to secondary review
                return history.push({
                  pathname: history.location.pathname.replace(
                    'confirmation',
                    'secondary-review',
                  ),
                  search: history.location.search,
                });
              }
              // Redirect to checkout
              return history.push({
                pathname: history.location.pathname.replace(
                  'confirmation',
                  'checkout',
                ),
                search: history.location.search,
              });
            }
          });
        }}
        ftfCoverage={state.ftfCoverage}
        geocoder={{
          addressAutocompleteService,
          addressGeocoderService,
        }}
        onContactUs={show}
        showPrograms={programContent.showPrograms}
        agencyProgramFlag={agencyProgramFlag}
      />
    </>
  );
};

export const ConfirmationPage = withPreloadedDataPage(
  _ConfirmationPage,
  confirmationPageDataLoader,
);
