import React from 'react';
import {useParams, Redirect} from 'react-router-dom';
import {Helmet} from 'react-helmet';
import {useProgram} from '../../components/ContentProvider';
import {ProgramLandingPageView} from '../../components/pages/ProgramLanding';
import {PageParams} from '../../lib/routing';

export const LandingPage = () => {
  const programContent = useProgram();
  const params = useParams<PageParams>();

  if (!programContent.landingPage) {
    return (
      <Redirect to={`/${params.partnership}/${params.program}/general-info`} />
    );
  }

  return (
    <>
      <Helmet>
        <title>
          {programContent.landingPage.pageTitle ?? programContent.pageTitle}
        </title>
      </Helmet>
      <ProgramLandingPageView
        content={programContent.landingPage}
        getStartedLink={`/${params.partnership}/${params.program}/general-info`}
      />
    </>
  );
};
