import React, {Fragment} from 'react';
import {useFela} from 'react-fela';

import {Spinner} from '@crucible-risk/spinner';

import {ChangeFunction, SaveFunction, Question} from './ApplicationQuestions';
import {QuestionInputSet} from './EditView';
import {Hr} from '../Hr';

import {TEXTAREA, INPUT_COLUMN, INPUT_ROW} from './styles';
import {childQuestions} from './child-questions';

interface TextAreaQuestionProps {
  disabled: boolean;
  question: Question;
  onChange: ChangeFunction;
  onSave: SaveFunction;
  questionInfo: Record<string, string>;
  companyName: string;
  active: boolean;
}

export const TextAreaQuestion: React.FC<TextAreaQuestionProps> = ({
  question,
  disabled,
  onChange,
  onSave,
  questionInfo,
  companyName,
  active,
}) => {
  const {css} = useFela<{intent: 'danger' | 'neutral'}>({
    intent: !question.answer_text && question.required ? 'danger' : 'neutral',
  });

  return (
    <Fragment key={question.id}>
      {/* Child Questions are indented and dont need an HR */}
      {childQuestions[question.id] && <Hr />}

      <QuestionInputSet
        companyName={companyName}
        questionInfo={questionInfo}
        question={question}
        textarea
        inputs={
          <div className={css(INPUT_ROW)}>
            <div className={css(INPUT_COLUMN)} style={{flexGrow: 1}}>
              <textarea
                className={css(TEXTAREA)}
                disabled={disabled}
                defaultValue={question.answer_text}
                value={question.answer_text}
                onChange={(event) => {
                  onChange(question, event.target.value);
                }}
                onBlur={() => {
                  onSave(question);
                }}
              />
            </div>
            <div
              className={css(INPUT_COLUMN)}
              style={{alignSelf: 'center', minWidth: 16}}
            >
              {active && <Spinner size={0} />}
            </div>
          </div>
        }
      />
    </Fragment>
  );
};
