import React from 'react';
import {useFela} from 'react-fela';

import {Typography} from '@crucible-risk/typography';
import {colors} from '@crucible-risk/theme';

import {
  TEXT_COLOR,
  STEPS_CONTAINER,
  ITEM_CONTAINER,
  DOT_ICON,
  CONTENT,
  TAIL_LINE,
  HALF_TAIL_LINE,
} from './styles';
import {Step} from './Step';

interface ItemProps {
  child?: JSX.Element;
  index: number;
  numSteps: number;
}

interface Props {
  children?: Array<JSX.Element>;
}

const Item = (props: ItemProps) => {
  const {child, index, numSteps} = props;
  const {css} = useFela({
    status: child?.props.status,
    index,
    numSteps,
  });

  let contentColor: keyof typeof colors | undefined;

  switch (child?.props.status) {
    case 'active':
    case 'finished':
    case 'half':
      contentColor = 'blue500';
      break;

    case 'disabled':
      contentColor = undefined;
  }

  return (
    <div className={css(ITEM_CONTAINER)}>
      {/** Dot icon */}
      <div className={css(DOT_ICON)} />

      {/** Content */}
      <div className={css(CONTENT)}>
        <Typography color={contentColor} weight="semibold">
          <div className={css(TEXT_COLOR)}>{child}</div>
        </Typography>
      </div>

      {/** Tail line if not last */}
      {index + 1 < numSteps && <div className={css(TAIL_LINE)} />}
      {index + 1 < numSteps && child?.props.status === 'half' && (
        <div className={css(HALF_TAIL_LINE)} />
      )}
    </div>
  );
};

export const Steps = ({children}: Props) => {
  const {css} = useFela();
  const numSteps = React.Children.count(children);

  return (
    <div className={css(STEPS_CONTAINER)}>
      {React.Children.map(children, (child, index) => {
        return <Item index={index} child={child} numSteps={numSteps} />;
      })}
    </div>
  );
};

Steps.Step = Step;
