import {
  Record,
  String,
  Array,
  Number,
  Union,
  Null,
  Literal,
  Static,
  Optional,
} from 'runtypes';

import {
  LifecycleStateSchema,
  InsuranceProgramSchema,
  MarketSchema,
} from '@crucible-risk/api-schema';

import {CurrencySchema} from './currency';
import {CoverageSchema} from './coverage';
import {ConfigurationSchema} from './configurations';

// see: https://github.com/crucible-risk/webserver/blob/953e76b/www/serializers/sku/insurance_policy.py#L102
const EndorsementSchema = Record({
  pdf_id: Number.Or(Null),
  form_code: String.Or(Null),
  label: String,
});

// see: https://github.com/crucible-risk/webserver/blob/9fa5561/www/serializers/sku/insurance_policy.py#L37
export const EmployeeCountSchema = Union(
  Literal('1-25'),
  Literal('26-50'),
  Literal('51-250'),
  Literal('251-1000'),
  Literal('1001+'),
);

export type EmployeeCount = Static<typeof EmployeeCountSchema>;

const InsurancePolicyDocumentSchema = Record({
  label: String,
  link: String,
  type: String,
});

export type InsurancePolicyDocument = Static<
  typeof InsurancePolicyDocumentSchema
>;

// see: https://github.com/crucible-risk/webserver/blob/0a256ec8c0ad290b478983c2536f7431e60dd74c/www/serializers/customerapi/insurance_policy.py#L375
const InsurancePolicyFields = {
  name: String,
  domain_names: Array(String),
  address: Record({
    city: String,
    country: String,
    line_1: String,
    line_2: Optional(String.Or(Null)),
    postcode: String,
    state: String,
    administrative_area: String,
    sub_administrative_area: String.Or(Null),
  }),
  industry_id: Number,
  uuid: String,
  application_questions_id: Number,
  limit: CurrencySchema.Or(Null),
  retention: CurrencySchema.Or(Null),
  coverages: Array(CoverageSchema),
  insurance_market: MarketSchema,
  end_date: String,
  effective_date: String,
  lifecycle_state: LifecycleStateSchema,
  endorsements: Array(EndorsementSchema),
  premium: CurrencySchema.Or(Null),
  program: InsuranceProgramSchema,
  gross_profit_net_revenue: CurrencySchema.Or(Null),
  revenue: CurrencySchema.Or(Null),
  employee_count: EmployeeCountSchema,
  email: String,
  affinity_referrer_uuid: Optional(String),
  policy_version: String.Or(Null),
  documents: Array(InsurancePolicyDocumentSchema).Or(Null),
  coalition_policy_number: String.Or(Null),
  phone_number: String.Or(Null),
  phone_type: Optional(String.Or(Null)),
  first_name: String.Or(Null),
  last_name: String.Or(Null),
  selected_configuration: ConfigurationSchema.Or(Null),
  renewal_of_id: Optional(String.Or(Null)),
  distribution_programs: Array(String).Or(Null),
};

// The need for this was defined when adding phone numbers to an insurance policy.  In the API, phone_number and phone_type are optional.
// But in the input form, it is required.  However, when we create quotes that don't have phone numbers in the response, Validation blows
// up and returns a validation error.  Because we have two different validation requirements based on form submission and API response,
// the below objects reflect the distinction between Form validation and API response validation

export const InsurancePolicySchema = Record(InsurancePolicyFields);
export const InsurancePolicyResponseSchema = Record({
  ...InsurancePolicyFields,
  phone_number: String.Or(Null),
  phone_type: String.Or(Null),
});

export type InsurancePolicy = Static<typeof InsurancePolicySchema>;

export type InsurancePolicyResponse = Static<
  typeof InsurancePolicyResponseSchema
>;
