import {IRenderer} from 'fela';

// what-input keeps the html element data-whatintent attribute updated as an
// import side-effect.
import 'what-input';

import {
  fontStacks,
  fontWeights,
  typeVariants,
  formatTypeVariant,
} from './typography';
import {colors} from './color';

export function globalStyle(renderer: IRenderer) {
  renderer.renderStatic(
    {
      MozOsxFontSmoothing: 'grayscale',
      WebkitFontSmoothing: 'antialiased',
      fontSmoothing: 'antialiased',
    },
    'html',
  );

  renderer.renderStatic(
    {
      outline: 'none',
    },
    'html[data-whatintent=mouse] *:focus, html[data-whatintent=touch] *:focus',
  );

  renderer.renderStatic(
    {
      fontWeight: fontWeights.bold,
    },
    'b, strong',
  );

  renderer.renderStatic(
    {
      ...formatTypeVariant(typeVariants.bodyRegular),
      fontFamily: fontStacks.base.join(', '),
      color: colors.bodyCopy,
    },
    'body',
  );
}

export function headerStyle(renderer: IRenderer) {
  renderer.renderStatic(
    {
      ...formatTypeVariant(typeVariants.bodyRegular),
      fontFamily: fontStacks.mono.join(', '),
      color: colors.bodyCopy,
    },
    '.h1,.h2,.h3,.h4,.h5,.h6',
  );
}
