import {tint} from 'polished';

import {RC} from '@crucible-risk/fela-renderer';
import {
  colors,
  formatTypeVariant,
  interactiveBorderRadius,
  fontStacks,
} from '@crucible-risk/theme';

import {sizes, intents, borderWidth} from './textInput.config';

export const containerStyle: RC<{size: keyof typeof sizes}> = ({
  size = 'regular',
}) => {
  return {
    display: 'flex',
    position: 'relative',
    alignItems: 'stretch',

    paddingLeft: sizes[size].padding + 4,
    paddingRight: sizes[size].padding + 4,
  };
};

export const inputStyle: RC<{size: keyof typeof sizes}> = ({
  size = 'regular',
}) => {
  return {
    width: '100%',
    flex: '1 1 auto',

    position: 'relative',
    zIndex: 1,

    order: 1,
    display: 'block',
    border: 'none',

    textOverflow: 'ellipsis',

    ...formatTypeVariant(sizes[size].typeVariant),

    // IE11 does not respect the input element's line-height and as a result you
    // must also provide a fixed height.
    height: sizes[size].height,
    lineHeight: sizes[size].height + 'px',

    color: colors.bodyCopy,

    borderRadius: interactiveBorderRadius,

    ':-webkit-autofill, :-webkit-autofill:hover, :-webkit-autofill:focus, :-webkit-autofill:active': {
      // This is a hacky override for the webpack input autocomplete styles. We
      // use a css animation to override the native styles defined with
      // with !important. Inspired by https://stackoverflow.com/a/60721653.
      // If the animation hack is ever fixed by webkit, there is another viable
      // alternative which uses a css transition delay instead.
      // see: https://webagility.com/posts/the-ultimate-list-of-hacks-for-chromes-forced-yellow-background-on-autocompleted-inputs
      // WebkitTransitionDelay: '99999s',
      animationName: {
        to: {
          background: 'transparent',
          color: 'inherit',
          // fontSize: sizes[size].typeVariant.size + 'px',
        },
      },
      animationDuration: '0s',
      animationFillMode: 'forwards',

      // Force the autocomplete suggestion text to have the correct style.
      // Inspired by https://stackoverflow.com/a/60379185.
      '::first-line': {
        fontFamily: fontStacks.base.join(', '),
        ...formatTypeVariant(sizes[size].typeVariant),
      },
    },

    '::placeholder': {
      color: colors.coolGray400,
    },

    // IE11 does not respect the placeholder unless it is highly specific
    // As fela and specificity don't mix, we apply !important to the specific -ms- prefix
    ':-ms-input-placeholder': {
      color: `${colors.coolGray400} !important`,
    },
  };
};

export const borderStyle: RC<{intent: keyof typeof intents}> = ({
  intent = 'primary',
}) => {
  return {
    nested: {
      '& ~ div:last-of-type': {
        position: 'absolute',
        top: '0',
        right: '0',
        bottom: '0',
        left: '0',

        pointerEvents: 'none',

        borderWidth,
        borderStyle: 'solid',
        borderColor: tint(0.5, intents[intent]),
        borderRadius: interactiveBorderRadius,

        background: colors.white,
      },

      ':read-only ~ div:last-of-type': {
        borderColor: colors.coolGray800,
        background: colors.coolGray900,
      },
    },
  };
};

export const appendStyle: RC = () => {
  return {
    flex: '0 0 auto',
    position: 'relative',
    zIndex: 1,

    display: 'flex',
    alignItems: 'center',
    color: colors.coolGray400,
  };
};

export const appendStartStyle: RC<{size: keyof typeof sizes}> = ({
  size = 'regular',
}) => {
  return {
    order: 0,
    paddingLeft: sizes[size].padding,
    paddingRight: sizes[size].padding - borderWidth,
    marginLeft: -sizes[size].padding - 4,
  };
};

export const appendEndStyle: RC<{size: keyof typeof sizes}> = ({
  size = 'regular',
}) => {
  return {
    order: 2,
    paddingRight: sizes[size].padding,
    paddingLeft: sizes[size].padding - borderWidth,
    marginRight: -sizes[size].padding - 4,
  };
};
