import React from 'react';
import {useFela} from 'react-fela';

import {colors} from '@crucible-risk/theme';
import {Spacing} from '@crucible-risk/spacing';
import {Spinner} from '@crucible-risk/spinner';
import {Typography} from '@crucible-risk/typography';

const FADE_DURATION_MS = 1000;

export const FullscreenLoading: React.FC<{message: string}> = ({message}) => {
  const {css} = useFela();

  return (
    <div
      className={css({
        position: 'absolute',
        top: 0,
        right: 0,
        bottom: 0,
        left: 0,
        overflow: 'hidden',
        zIndex: 99999,
      })}
    >
      <div
        className={css({
          position: 'absolute',
          top: 0,
          right: 0,
          bottom: 0,
          left: 0,
          background: colors.white,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          transformOrigin: '50%',
          transition: `opacity ${FADE_DURATION_MS}ms`,
          opacity: 1,
        })}
      >
        <Spinner size={64} color="blue500" />
        <div className={css({height: 0})}>
          <Spacing height="16" />
          <Typography variant="labelRegular">{message}</Typography>
        </div>
      </div>
    </div>
  );
};
