import React, {Fragment} from 'react';
import {useFela} from 'react-fela';

import {Typography} from '@crucible-risk/typography';
import {Spacing} from '@crucible-risk/spacing';

import {Checkbox} from '../Checkbox';
import {ATTESTATION_HEADER, ROW} from './styles';
import {FormValues} from '../../lib/form';
import {CheckoutPageType} from '../../lib/content';
import {Markdown} from '../Markdown';

export interface Data {
  attestation_legal: boolean;
  attestation_terms: boolean;
  partner_attestation: boolean;
}

export type ChangeFunction = (
  field: keyof Data,
  value: FormValues | null,
) => void;

export interface Questions {
  attestation_legal: string;
  attestation_terms: string;
  partner_attestation?: string;
}

export interface Props {
  data?: Data;
  onChange: ChangeFunction;
  questions?: Questions;
  content: CheckoutPageType;
  error: Record<keyof Data, string | undefined>;
}

const AttestationHeader = () => {
  const {css} = useFela();

  return (
    <Typography
      className={css(ATTESTATION_HEADER)}
      weight="semibold"
      color="black"
      variant="bodySmall"
    >
      By submitting this form you consent to Coalition&apos;s&nbsp;
      <Typography color="blue500">
        <a
          href="https://www.coalitioninc.com/legal/terms"
          target="_blank"
          rel="noopener noreferrer"
        >
          Terms of Use
        </a>
      </Typography>
      &nbsp;and &nbsp;
      <Typography color="blue500">
        <a
          href="https://www.coalitioninc.com/legal/privacy"
          target="_blank"
          rel="noopener noreferrer"
        >
          Privacy Policy
        </a>
      </Typography>
      .
    </Typography>
  );
};

export const AttestationQuestions = ({
  data,
  onChange,
  questions,
  content,
  error,
}: Props) => {
  const {css} = useFela();

  return (
    <div>
      <AttestationHeader />
      <Spacing bottom="16" />

      {questions &&
        Object.keys(questions).map((key, index) => {
          if (questions[key as keyof Questions] === undefined) {
            return null;
          }

          return (
            <Fragment key={key}>
              <label className={css(ROW)} htmlFor={key}>
                <Checkbox
                  id={key}
                  name={key}
                  checked={!!data && data[key as keyof Questions]}
                  onChange={(value) => {
                    onChange(key as keyof Questions, value);
                  }}
                />

                <Spacing right="8" />

                <Typography className="body5 fg-body" fill variant="bodyXSmall">
                  <Markdown markdown={questions[key as keyof Questions]} />
                </Typography>
              </label>
              {error[key as keyof Questions] !== undefined && (
                <Spacing left="24">
                  <Typography
                    className="body5 fg-body"
                    color="red500"
                    variant="bodySmall"
                  >
                    {error[key as keyof Questions]}
                  </Typography>
                </Spacing>
              )}
              {index < Object.keys(questions).length && <Spacing bottom="16" />}
            </Fragment>
          );
        })}
    </div>
  );
};

AttestationQuestions.displayName = 'AttestationQuestions';
