import * as React from 'react';

import {
  InsurancePolicy,
  Configuration,
  ApplicationQuestions,
} from '@crucible-risk/sku-api-schema';
import {
  useGeneralInfoForm,
  getGeneralInfoValuesFromInsurancePolicy,
} from '../../hooks/useGeneralInfoForm';
import {useConfigurationState} from './useConfigurationState';
import {useApplicationQuestionsState} from './useApplicationQuestionsState';
import {useQuoteState} from './useQuoteState';
import {affinityReferrerUUID} from '/hooks/useAffinityReferrer';

export type UseConfigurationStateProps = {
  sessionId: string;
  initialConfiguration: Configuration | null;
  insurancePolicy?: InsurancePolicy;
  initialQuestions: ApplicationQuestions;
  agencyProgramFlag: boolean;
};

export const useConfirmationPageState = ({
  sessionId,
  initialConfiguration,
  insurancePolicy,
  initialQuestions,
  agencyProgramFlag,
}: UseConfigurationStateProps) => {
  // TODO: Get rid of this - it is no longer necessary now that we do not
  // allow editing on the confirmation page.  The only reason we're leaving
  // it for now is due to how tangled the components and state are.
  const [generalInfoState] = useGeneralInfoForm({
    initialValues: insurancePolicy
      ? getGeneralInfoValuesFromInsurancePolicy(
          insurancePolicy,
          affinityReferrerUUID ?? '',
        )
      : {},
    sessionId: sessionId ?? '',
    agencyProgramFlag,
    defaultProgram: undefined,
    defaultEndDate: undefined,
  });

  const [configurationState, configurationActions] = useConfigurationState(
    sessionId,
    initialConfiguration,
  );

  const [quoteState, quoteActions] = useQuoteState({sessionId});

  const [questionsState, questionsActions] = useApplicationQuestionsState({
    sessionId,
    initialQuestions,
  });

  const hasFTF = React.useMemo(
    () =>
      initialConfiguration?.coverages.find(
        (coverage) => coverage.coverage === 'funds_transfer',
      ),
    [initialConfiguration],
  );

  return [
    {
      ftfCoverage: hasFTF,
      configuration: {...configurationState},
      generalInfo: {...generalInfoState},
      quote: {...quoteState},
      applicationQuestions: questionsState,
    },
    {
      configuration: {...configurationActions},
      quote: {...quoteActions},
      applicationQuestions: questionsActions,
    },
  ] as const;
};
