import {
  Boolean,
  String,
  Record,
  Dictionary,
  Static,
  Array,
  Number,
  Partial,
  Optional,
} from 'runtypes';
import {createClient} from 'contentful';
import {
  contentfulApiKey,
  contentfulEnvironment,
  contentfulSpace,
  contentfulPreview,
} from '../config';
import {Theme} from './theme';

import {
  ContentClient,
  Partnership,
  Program,
  ContentBlock,
  IconContentBlock,
  ImageAsset,
  FieldBlock,
  LinkBlock,
  SizeableContentBlock,
  GeneralInfoPage,
  SelectPlanPage,
  ConfirmationPage,
  CheckoutPage,
  SuccessPage,
  QuoteNotSupportedPage,
  SecondaryReviewPage,
  Asset,
  LandingPage,
  LinkCard,
  InfoBlock,
  LandingPageValueProps,
  LandingPageAdditionalValue,
} from './content';

/**
 * The expected items from the contentful response. Specifically, the stuff we care about
 */
const ContentfulEntry = Record({
  sys: Record({
    id: String,
  }),
});

const ContentfulAsset = ContentfulEntry.And(
  Record({
    fields: Record({
      title: String,
      file: Record({
        url: String,
        details: Record({
          size: Number,
        }).And(
          Partial({
            image: Record({
              width: Number,
              height: Number,
            }),
          }),
        ),
        fileName: String,
        contentType: String,
      }),
    }),
  }),
);

const ContentfulLinkCard = ContentfulEntry.And(
  Record({
    fields: Record({
      mainText: String,
      superText: String,
      linkText: String,
      linkIcon: String,
    }).And(
      Partial({
        linkHref: String,
        linkAsset: ContentfulAsset,
      }),
    ),
  }),
);

const ContentfulInfoBlock = ContentfulEntry.And(
  Partial({
    fields: Partial({
      title: String,
      bodyText: String,
      image: ContentfulAsset,
      extra: Array(String),
    }),
  }),
);

/* ContentfulPrimary AKA Affinity Partnership */
const ContentfulPrimary = ContentfulEntry.And(
  Record({
    fields: Record({
      name: String,
      slug: String,
    }).And(
      Partial({
        logo: ContentfulAsset,
      }),
    ),
  }),
);

const ContentfulLegal = ContentfulEntry.And(
  Record({
    fields: Record({
      title: String,
      terms: String,
    }),
  }),
);

// The Set of information for the Value Props section of the Landing Page. This is a reference in the Landing page,
// since all Landing Pages should be referencing the same default text and images.
const ContentfulLandingPageValueProps = ContentfulEntry.And(
  Record({
    fields: Record({
      title: String,
      subsections: Array(ContentfulInfoBlock),
    }),
  }),
);

// The Set of information for the Additional Value section of the Landing Page. This is a reference in the Landing page,
// since all Landing Pages should be referencing the same default text and images.
const ContentfulLandingPageAdditionalValue = ContentfulEntry.And(
  Record({
    fields: Record({
      title: ContentfulInfoBlock,
      subsections: Array(ContentfulInfoBlock),
    }),
  }),
);

const ContentfulLandingPage = ContentfulEntry.And(
  Record({
    fields: Record({
      heading: String,
      body: String,
      callToActionText: String,
      image: ContentfulAsset,
    }).And(
      Partial({
        pageTitle: String,
        contentBlocks: Array(IconContentBlock),
        linkCards: Array(ContentfulLinkCard),
        introStats: Array(ContentfulInfoBlock),
        valueProps: ContentfulLandingPageValueProps,
        additionalValue: ContentfulLandingPageAdditionalValue,
      }),
    ),
  }),
);

const ContentfulGeneralInfoPage = ContentfulEntry.And(
  Record({
    fields: Record({
      name: String,
      heading: String,
      subHeading: String,
      form: Dictionary(FieldBlock),
      button: String,
      image: ContentfulAsset,
      imageSubText: Record({left: ContentBlock, right: ContentBlock}),
      body: Optional(ContentBlock),
      features: Optional(
        Record({
          heading: String,
          footer: String,
          left: Array(SizeableContentBlock),
          right: Array(SizeableContentBlock),
        }),
      ),
      footer: String,
      legal: LinkBlock,
      claims: LinkBlock,
    }).And(
      Partial({
        pageTitle: String,
      }),
    ),
  }),
);

const ContentfulSelectPlanPage = ContentfulEntry.And(
  Record({
    fields: Record({
      name: String,
      heading: String,
      recommended: ContentBlock,
      card: Record({
        body: String,
        pricePrefix: String,
        button: String,
        footer: String,
      }),
      image: ContentfulAsset,
      body: ContentBlock,
      coverages: Array(ContentBlock),
      footer: ContentBlock.And(
        Record({
          content: Array(
            ContentBlock.And(
              Record({
                icon: String,
              }),
            ),
          ),
        }),
      ),
      modal: Record({
        heading: String,
        body: String,
        ftf: Record({
          heading: String,
          prefix: String,
          button: String,
        }),
        current: Record({
          heading: String,
          prefix: String,
          button: String,
        }),
      }),
      coveragesHeader: String,
    }).And(
      Partial({
        pageTitle: String,
      }),
    ),
  }),
);

const ContentfulConfirmationPage = ContentfulEntry.And(
  Record({
    fields: Record({
      heading: String,
      selectedPlan: Record({
        name: String,
        limit: String,
        deductible: String,
        premium: String,
      }),
      form: Dictionary(FieldBlock),
      correctButton: String,
      editButton: String,
      saveButton: String,
      cancelButton: String,
      ftfModal: Record({
        continueButton: String,
        cancelButton: String,
        body: String,
      }),
      questionInfo: Dictionary(String),
    }).And(
      Partial({
        pageTitle: String,
      }),
    ),
  }),
);

const ContentfulCheckoutPage = ContentfulEntry.And(
  Record({
    fields: Record({
      heading: String,
      payment: Record({
        label: String,
        fields: Dictionary(FieldBlock),
      }),
      review: Record({
        label: String,
        heading: String,
        legal: String,
        signature: FieldBlock,
        button: String,
        footer: String,
      }),
      selected: Record({
        heading: String,
        limit: String,
        deductible: String,
        effectiveDate: String,
        downloadQuote: String,
        changePlan: String,
        premium: String,
        total: String,
        footer: String,
      }),
      footer: ContentBlock.And(
        Record({
          content: Array(
            ContentBlock.And(
              Record({
                icon: String,
              }),
            ),
          ),
        }),
      ),
      legal: ContentfulLegal,
      partnerAttestation: Optional(String),
    }).And(
      Partial({
        pageTitle: String,
      }),
    ),
  }),
);

const ContentfulSuccessPage = ContentfulEntry.And(
  Record({
    fields: Record({
      heading: String,
      body: String,
      image: ContentfulAsset,
      details: Record({
        heading: String,
        policyNumber: String,
        effectiveDate: String,
        policyButton: String,
        riskAssessmentButton: String,
      }),
      footer: ContentBlock.And(
        Record({
          content: Array(
            ContentBlock.And(
              Record({
                icon: String,
              }),
            ),
          ),
        }),
      ),
    }).And(
      Partial({
        pageTitle: String,
      }),
    ),
  }),
);

const ContentfulQuoteNotSupportedPage = ContentfulEntry.And(
  Record({
    fields: Record({
      heading: String,
      body: String,
      link: String,
      image: ContentfulAsset,
    }).And(
      Partial({
        pageTitle: String,
      }),
    ),
  }),
);

const ContentfulSecondaryReviewPage = ContentfulEntry.And(
  Record({
    fields: Record({
      heading: String,
      body: String,
      image: ContentfulAsset,
    }).And(
      Partial({
        pageTitle: String,
      }),
    ),
  }),
);

/* ContentfulSecondary AKA Affinity Program */
const ContentfulSecondary = ContentfulEntry.And(
  Record({
    fields: Record({
      name: String,
      pageTitle: String,
      slug: String,
      primary: ContentfulPrimary,
      affinityReferrerUuid: String,
      algoliaIndustriesIndex: String,
      applicationQuestionDefaultAnswers: Dictionary(String),
      generalInfoPage: ContentfulGeneralInfoPage,
      selectPlanPage: ContentfulSelectPlanPage,
      confirmationPage: ContentfulConfirmationPage,
      checkoutPage: ContentfulCheckoutPage,
      successPage: ContentfulSuccessPage,
      quoteNotSupportedPage: ContentfulQuoteNotSupportedPage,
      secondaryReviewPage: ContentfulSecondaryReviewPage,
      agencyProgramFlag: Boolean,
    }).And(
      Partial({
        stylesheet: String,
        logo: ContentfulAsset,
        landingPage: ContentfulLandingPage,
        theme: Theme,
        fonts: Array(String),
        showPrograms: Boolean,
        defaultProgram: String,
        defaultEndDate: String,
      }),
    ),
  }),
);

export class ContentfulContentClient implements ContentClient {
  private client: ReturnType<typeof createClient>;

  constructor({
    space = contentfulSpace,
    environment = contentfulEnvironment,
    apiKey = contentfulApiKey,
    preview = contentfulPreview,
  }: {
    space?: string;
    environment?: string;
    apiKey?: string;
    preview?: boolean;
  } = {}) {
    this.client = createClient({
      host: preview ? 'preview.contentful.com' : 'cdn.contentful.com',
      accessToken: apiKey,
      space,
      environment,
    });
  }

  private mapLandingPage(
    page: Static<typeof ContentfulLandingPage>,
  ): Static<typeof LandingPage> {
    return {
      pageTitle: page.fields.pageTitle,
      body: page.fields.body,
      callToActionText: page.fields.callToActionText,
      heading: page.fields.heading,
      image: this.mapImageAsset(page.fields.image),
      contentBlocks: page.fields.contentBlocks,
      linkCards: page.fields.linkCards?.map((entry) => this.mapLinkCard(entry)),
      introStats: page.fields.introStats?.map((entry) =>
        this.mapInfoBlock(entry),
      ),
      valueProps: page.fields.valueProps
        ? this.mapValueProps(page.fields.valueProps)
        : undefined,
      additionalValue: page.fields.additionalValue
        ? this.mapAdditionalValues(page.fields.additionalValue)
        : undefined,
    };
  }

  private mapGeneralInfoPage(
    page: Static<typeof ContentfulGeneralInfoPage>,
  ): Static<typeof GeneralInfoPage> {
    return {
      pageTitle: page.fields.pageTitle,
      body: page.fields.body,
      button: page.fields.button,
      claims: page.fields.claims,
      features: page.fields.features,
      footer: page.fields.footer,
      form: page.fields.form,
      heading: page.fields.heading,
      image: this.mapImageAsset(page.fields.image),
      imageSubText: page.fields.imageSubText,
      legal: page.fields.legal,
      name: page.fields.name,
      subHeading: page.fields.subHeading,
    };
  }

  private mapSelectPlanPage(
    page: Static<typeof ContentfulSelectPlanPage>,
  ): Static<typeof SelectPlanPage> {
    return {
      pageTitle: page.fields.pageTitle,
      card: page.fields.card,
      coverages: page.fields.coverages,
      footer: page.fields.footer,
      heading: page.fields.heading,
      image: this.mapImageAsset(page.fields.image),
      body: page.fields.body,
      name: page.fields.name,
      recommended: page.fields.recommended,
      modal: page.fields.modal,
      coveragesHeader: page.fields.coveragesHeader,
    };
  }

  private mapConfirmationPage(
    page: Static<typeof ContentfulConfirmationPage>,
  ): Static<typeof ConfirmationPage> {
    return {
      pageTitle: page.fields.pageTitle,
      heading: page.fields.heading,
      form: page.fields.form,
      selectedPlan: page.fields.selectedPlan,
      saveButton: page.fields.saveButton,
      cancelButton: page.fields.cancelButton,
      correctButton: page.fields.correctButton,
      editButton: page.fields.editButton,
      ftfModal: page.fields.ftfModal,
      questionInfo: page.fields.questionInfo,
    };
  }

  private mapCheckoutPage(
    page: Static<typeof ContentfulCheckoutPage>,
  ): Static<typeof CheckoutPage> {
    return {
      pageTitle: page.fields.pageTitle,
      heading: page.fields.heading,
      selected: page.fields.selected,
      payment: page.fields.payment,
      review: page.fields.review,
      footer: page.fields.footer,
      legal: page.fields.legal.fields.terms,
      partnerAttestation: page.fields.partnerAttestation,
    };
  }

  private mapSuccessPage(
    page: Static<typeof ContentfulSuccessPage>,
  ): Static<typeof SuccessPage> {
    return {
      pageTitle: page.fields.pageTitle,
      heading: page.fields.heading,
      body: page.fields.body,
      image: this.mapImageAsset(page.fields.image),
      details: page.fields.details,
      footer: page.fields.footer,
    };
  }

  private mapQuoteNotSupportedPage(
    page: Static<typeof ContentfulQuoteNotSupportedPage>,
  ): Static<typeof QuoteNotSupportedPage> {
    return {
      pageTitle: page.fields.pageTitle,
      heading: page.fields.heading,
      body: page.fields.body,
      image: this.mapImageAsset(page.fields.image),
      link: page.fields.link,
    };
  }

  private mapSecondaryReviewPage(
    page: Static<typeof ContentfulSecondaryReviewPage>,
  ): Static<typeof SecondaryReviewPage> {
    return {
      pageTitle: page.fields.pageTitle,
      heading: page.fields.heading,
      body: page.fields.body,
      image: this.mapImageAsset(page.fields.image),
    };
  }

  private mapAsset(
    asset: Static<typeof ContentfulAsset>,
  ): Static<typeof Asset> {
    return {
      id: asset.sys.id,
      title: asset.fields.title,
      fileName: asset.fields.file.fileName,
      fileType: asset.fields.file.contentType,
      url: asset.fields.file.url,
    };
  }

  private mapImageAsset(
    asset: Static<typeof ContentfulAsset>,
  ): Static<typeof ImageAsset> {
    return {
      id: asset.sys.id,
      title: asset.fields.title,
      fileName: asset.fields.file.fileName,
      fileType: asset.fields.file.contentType,
      height: asset.fields.file.details.image?.height ?? 0,
      width: asset.fields.file.details.image?.width ?? 0,
      url: asset.fields.file.url,
    };
  }

  private mapLinkCard(
    card: Static<typeof ContentfulLinkCard>,
  ): Static<typeof LinkCard> {
    return {
      mainText: card.fields.mainText,
      linkAsset: card.fields.linkAsset
        ? this.mapAsset(card.fields.linkAsset)
        : undefined,
      linkHref: card.fields.linkHref,
      linkIcon: card.fields.linkIcon,
      linkText: card.fields.linkText,
      superText: card.fields.superText,
    };
  }

  private mapInfoBlock(
    block: Static<typeof ContentfulInfoBlock>,
  ): Static<typeof InfoBlock> {
    return {
      title: block.fields?.title,
      icon: block.fields?.image
        ? this.mapImageAsset(block.fields.image)
        : undefined,
      bodyText: block.fields?.bodyText,
      extra: block.fields?.extra,
    };
  }

  private mapValueProps(
    block: Static<typeof ContentfulLandingPageValueProps>,
  ): Static<typeof LandingPageValueProps> {
    return {
      title: block.fields?.title,
      subsections: block.fields?.subsections
        ? block.fields.subsections?.map((entry) => this.mapInfoBlock(entry))
        : undefined,
    };
  }

  private mapAdditionalValues(
    block: Static<typeof ContentfulLandingPageAdditionalValue>,
  ): Static<typeof LandingPageAdditionalValue> {
    return {
      title: this.mapInfoBlock(block.fields?.title),
      subsections: block.fields?.subsections
        ? block.fields.subsections?.map((entry) => this.mapInfoBlock(entry))
        : undefined,
    };
  }

  private mapSecondary(
    program: Static<typeof ContentfulSecondary>,
  ): Static<typeof Program> {
    return {
      id: program.sys.id,
      logo: program.fields.logo
        ? this.mapImageAsset(program.fields.logo)
        : undefined,
      name: program.fields.name,
      slug: program.fields.slug,
      pageTitle: program.fields.pageTitle,
      partnership: this.mapPrimary(program.fields.primary),
      algoliaIndustriesIndex: program.fields.algoliaIndustriesIndex,
      agencyProgramFlag: program.fields.agencyProgramFlag,
      showPrograms: program.fields.showPrograms,
      defaultProgram: program.fields.defaultProgram,
      applicationQuestionDefaultAnswers:
        program.fields.applicationQuestionDefaultAnswers,
      generalInfoPage: this.mapGeneralInfoPage(program.fields.generalInfoPage),
      selectPlanPage: this.mapSelectPlanPage(program.fields.selectPlanPage),
      confirmationPage: this.mapConfirmationPage(
        program.fields.confirmationPage,
      ),
      checkoutPage: this.mapCheckoutPage(program.fields.checkoutPage),
      successPage: this.mapSuccessPage(program.fields.successPage),
      quoteNotSupportedPage: this.mapQuoteNotSupportedPage(
        program.fields.quoteNotSupportedPage,
      ),
      secondaryReviewPage: this.mapSecondaryReviewPage(
        program.fields.secondaryReviewPage,
      ),
      landingPage: program.fields.landingPage
        ? this.mapLandingPage(program.fields.landingPage)
        : undefined,
      stylesheet: program.fields.stylesheet,
      theme: program.fields.theme,
      fonts: program.fields.fonts,
      defaultEndDate: program.fields.defaultEndDate,
    };
  }

  private mapPrimary(
    partnership: Static<typeof ContentfulPrimary>,
  ): Static<typeof Partnership> {
    return {
      id: partnership.sys.id,
      logo: partnership.fields.logo
        ? this.mapImageAsset(partnership.fields.logo)
        : undefined,
      name: partnership.fields.name,
      slug: partnership.fields.slug,
    };
  }

  /** Simple cache object to prevent multiple content requests within the same session */
  static cachedContent: {[key: string]: Static<typeof Program>} = {};

  getProgram(program: string, partnership: string) {
    const cacheKey = `${partnership}-${program}`;

    if (ContentfulContentClient.cachedContent[cacheKey]) {
      return Promise.resolve(ContentfulContentClient.cachedContent[cacheKey]);
    }

    return this.client
      .getEntries({
        include: 3,
        content_type: 'secondary',
        'fields.slug': program,
        'fields.primary.sys.contentType.sys.id': 'primary',
        'fields.primary.fields.slug': partnership,
      })
      .then((response) => Array(ContentfulSecondary).check(response.items))
      .then((items) => items.map((item) => this.mapSecondary(item)))
      .then((programs) => programs[0])
      .then((programContent) => {
        ContentfulContentClient.cachedContent[cacheKey] = programContent;
        return programContent;
      });
  }
}

export const createContentfulClient = (
  clientArgs: {
    space?: string;
    environment?: string;
    apiKey?: string;
    preview?: boolean;
  } = {},
): ContentClient => {
  const client = new ContentfulContentClient(clientArgs);
  return {
    getProgram: (program: string, partnership: string) => {
      return client.getProgram(program, partnership);
    },
  };
};
