import * as React from 'react';
import {Helmet} from 'react-helmet';

import {useProgram} from '../../components/ContentProvider';
import {SecondaryReview} from '../../components/pages/SecondaryReview';
import {withPreloadedDataPage} from '../../lib/withPreloadedDataPage';
import {
  SecondaryReviewPageProps,
  secondaryReviewPageDataLoader,
} from './loader';

const WrappedSecondaryReviewPage: React.FC<SecondaryReviewPageProps> = ({
  insurancePolicy,
}) => {
  const program = useProgram();

  return (
    <>
      <Helmet>
        <title>
          {program.secondaryReviewPage.pageTitle ?? program.pageTitle}
        </title>
      </Helmet>
      <SecondaryReview
        content={program.secondaryReviewPage}
        insurancePolicy={insurancePolicy}
      />
    </>
  );
};

/**
 * Add preloaded data to the page
 */
export const SecondaryReviewPage = withPreloadedDataPage<
  SecondaryReviewPageProps
>(WrappedSecondaryReviewPage, secondaryReviewPageDataLoader);
