import * as React from 'react';
import {useFela} from 'react-fela';

import {Typography as T} from '@crucible-risk/typography';
import {Spacing} from '@crucible-risk/spacing';

import {Tooltip} from '/components/Tooltip';
import {Redacted} from '/components/Redacted';

import type {
  GeneralInfoFormFieldValue,
  GeneralInfoFormValues,
} from '/hooks/useGeneralInfoForm';

import {StyleProps, INPUT, INPUT_ROW, INPUTS, LABEL, ERROR} from './styles';
import {useCompanyDetailsContext, Intent} from './CompanyDetailsContext';

type FieldChangeHandler = (value: GeneralInfoFormFieldValue) => void;
type FieldBlurHandler = () => void;

export type RenderFunctionProps = {
  name: string;
  onChange: FieldChangeHandler;
  onBlur: FieldBlurHandler;
  placeholder: string;
  value: GeneralInfoFormFieldValue;
  intent: Intent;
};

export type RenderDisplayModeProps = {
  value: GeneralInfoFormFieldValue;
};

export type CompanyDetailsInputProps = {
  field: keyof GeneralInfoFormValues;
  plain?: boolean;
  redacted?: boolean;
  exact?: boolean;
  tooltip?: string;
  children: (props: RenderFunctionProps) => JSX.Element | null;
  renderDisplay?: (props: RenderDisplayModeProps) => JSX.Element | null;
};

export const CompanyDetailsInput = ({
  field,
  plain = false,
  redacted = false,
  exact = false,
  tooltip,
  renderDisplay,
  children,
}: CompanyDetailsInputProps) => {
  const {
    labelStyle,
    label,
    hidden,
    editing,
    error,
    ...props
  } = useCompanyDetailsContext(field);
  const {css} = useFela<StyleProps>({labelStyle});

  const errorMessage = error !== undefined && (
    <div className={css(ERROR)}>
      <T color="red500" variant="bodySmall">
        {error}
      </T>
    </div>
  );

  if (hidden) {
    return null;
  }

  const contents =
    exact || editing ? (
      children({
        ...props,
      })
    ) : (
      <T className="body3 fg-body" weight="semibold">
        {renderDisplay
          ? renderDisplay({value: props.value})
          : props.value?.toString()}
      </T>
    );

  const input = redacted ? <Redacted>{contents}</Redacted> : contents;

  const typography =
    labelStyle === 'inline'
      ? {}
      : ({
          variant: 'bodyXSmall',
          weight: 'semibold',
          transform: 'uppercase',
        } as const);

  return plain ? (
    <>
      {input}
      <Spacing height="8" />
      {errorMessage}
    </>
  ) : (
    <>
      <div className={css(INPUT_ROW)}>
        <div className={css(LABEL)}>
          <T
            {...typography}
            color="bodyCopy"
            className={`fg-body ${labelStyle === 'inline' ? 'body4' : 'body5'}`}
          >
            {label}
          </T>{' '}
          {tooltip !== undefined && <Tooltip info={tooltip} field={field} />}
        </div>

        <div className={css(INPUTS)}>
          <div className={css(INPUT)}>{input}</div>
        </div>
      </div>
      {errorMessage}
    </>
  );
};
