import React from 'react';

import {ContentClient, ProgramType} from '/lib/content';

export type ContentProviderProps = {
  contentClient: ContentClient;
  partnership: string;
  program: string;
  children: React.ReactNode;
};

type State = {
  program: ProgramType | null;
  isLoading: boolean;
};

// eslint-disable-next-line
// @ts-ignore
const ContentContext = React.createContext<ProgramType>();

export const ContentProvider = ({
  children,
  partnership,
  program,
  contentClient,
}: ContentProviderProps) => {
  // We combine content & isLoading into a single useState in order to bundle our renders when
  // we update state
  // setState usually batches renders, but not when called in an async function/promise
  const [state, setState] = React.useState<State>({
    program: null,
    isLoading: true,
  });
  const isMounted = React.useRef<boolean>(true);
  const requestId = React.useRef<number>(0);

  // Used to prevent setState errors if component gets unmounted
  React.useEffect(
    () => () => {
      isMounted.current = false;
    },
    [],
  );

  React.useEffect(() => {
    // This serves as a cancellation token of sorts so we only commit the most recent request
    // Unlikely to be necessary, but can prevent flicker issues if someone somehow moves from
    // one partnership to another within the same session
    const id = ++requestId.current;
    setState((prev) => ({...prev, isLoading: true}));

    contentClient.getProgram(program, partnership).then((requestedContent) => {
      if (isMounted.current && requestId.current === id) {
        setState({program: requestedContent, isLoading: false});
      }
    });
    // TODO: Handle error
  }, [contentClient, partnership, program]);

  if (!state.program) {
    return null;
  }

  return (
    <ContentContext.Provider value={state.program}>
      {children}
    </ContentContext.Provider>
  );
};

export const useProgram = (): ProgramType => React.useContext(ContentContext);
