import {Configuration} from '@crucible-risk/sku-api-schema';
import {History} from 'history';
import {createClient} from '../../lib/api';
import {getSession, storeConfigurationId} from '../../lib/session';
import {CreateActions, Reducer} from '../../lib/state';
import {PageParams} from '../../lib/routing';
import {UnknownErrorException} from '../../lib/exceptions';

interface SelectPlanStateManagerProps {
  configurations: Array<Configuration>;
  sessionId: string;
  history: History;
  pageParams: PageParams;
}

interface WithFTFConfigurations {
  withoutFTF: Configuration;
  withFTF: Configuration;
}

interface SelectPlanState {
  submittingId?: number;
  submitting: boolean;
  error?: Error;
  ftfConfigurations?: WithFTFConfigurations;
}

type SelectPlanActionTypes =
  | {type: 'POSTING_CONFIGURATION'; submittingId: number}
  | {type: 'ERROR_POSTING'; error: Error}
  | {type: 'FTF_CONFIGURATION'; ftfConfigurations: WithFTFConfigurations}
  | {type: 'CLOSE_FTF'};

interface SelectPlanActions {
  selectPlan: (id: number) => void;
  closeFTF: () => void;
}

export const createSelectPlanStateManager = ({
  sessionId,
  history,
  configurations,
  pageParams,
}: SelectPlanStateManagerProps) => {
  const initialState: SelectPlanState = {
    submitting: false,
  };

  const reducer: Reducer<SelectPlanState, SelectPlanActionTypes> = (
    state,
    action,
  ) => {
    switch (action.type) {
      case 'POSTING_CONFIGURATION':
        return {
          ...state,
          submitting: true,
          submittingId: action.submittingId,
          error: undefined,
        };
      case 'ERROR_POSTING': {
        return {
          ...state,
          submitting: false,
          submittingId: undefined,
          error: action.error,
        };
      }
      case 'FTF_CONFIGURATION':
        return {...state, ftfConfigurations: action.ftfConfigurations};
      case 'CLOSE_FTF':
        return {...state, ftfConfigurations: undefined};
    }
    return state;
  };

  const relatedConfigurations = (id: number) =>
    configurations.filter(
      (configuration) => configuration.base_configuration_id === id,
    );

  const createActions: CreateActions<
    SelectPlanState,
    SelectPlanActions,
    SelectPlanActionTypes
  > = (dispatch, getState) => {
    const _selectPlan = (id: number): void => {
      dispatch({type: 'POSTING_CONFIGURATION', submittingId: id});

      const client = createClient(getSession(sessionId));
      client
        .setConfiguration(id)
        .then((response) => {
          if (!response.ok) {
            throw new UnknownErrorException();
          }
          // storing configuration id is necessary here because we will need it to clone the
          // insurance policy when the user makes any changes to QA on Configuration page
          storeConfigurationId(sessionId, id);

          history.push(
            `/${pageParams.partnership}/${pageParams.program}/confirmation?session=${sessionId}`,
          );
        })
        .catch((error) => dispatch({type: 'ERROR_POSTING', error}));
    };

    const selectPlan = (id: number): void => {
      const related = relatedConfigurations(id);
      const configuration = configurations.find(
        (_configuration) => _configuration.id === id,
      );

      if (configuration) {
        if (getState().ftfConfigurations || related.length === 0) {
          _selectPlan(id);
        } else {
          dispatch({
            type: 'FTF_CONFIGURATION',
            ftfConfigurations: {
              withoutFTF: configuration,
              withFTF: related[0],
            },
          });
        }
      }
    };

    return {selectPlan, closeFTF: () => dispatch({type: 'CLOSE_FTF'})};
  };

  return {initialState, reducer, createActions};
};
