import React from 'react';

import {Alert} from '@crucible-risk/alert';
import {Typography as T} from '@crucible-risk/typography';
import {Spacing} from '@crucible-risk/spacing';
import {useSentryCaptureException} from '@crucible-risk/react-monitoring';

export const ErrorAlert: React.FC<{
  error: string;
  onOpenContact: () => void;
}> = ({error, onOpenContact}) => {
  const handleOpenContact = () => {
    onOpenContact();
  };
  let message = null;
  const captureException = useSentryCaptureException();

  // Effects
  React.useEffect((): void => {
    if (error !== 'license-error') {
      return;
    }
    void captureException(error);
  }, [captureException, error]);

  switch (error) {
    case 'payment-error':
      message = (
        <>
          Something went wrong with your payment. Please check that your card
          information is correct and try again, or{' '}
          <button type="button" onClick={handleOpenContact}>
            <T weight="semibold">contact us</T>
          </button>{' '}
          if this problem persists.
        </>
      );
      break;

    case 'effective-date-too-far':
      message = (
        <>
          The effective date is too far in the future. Payments can be made up
          to 30 days before the effective date. Please{' '}
          <button type="button" onClick={handleOpenContact}>
            <T weight="semibold">contact customer service</T>
          </button>{' '}
          if you need help.
        </>
      );
      break;

    case 'license-error':
      message = (
        <>
          We need to review the license before issuing the policy. Please{' '}
          <button type="button" onClick={handleOpenContact}>
            <T weight="semibold">contact customer service</T>
          </button>{' '}
          to bind your policy.
        </>
      );
      break;

    default:
      message = (
        <>
          Something’s gone wrong. Please refresh, or{' '}
          <button type="button" onClick={handleOpenContact}>
            <T weight="semibold">contact us</T>
          </button>{' '}
          if this problem persists.
        </>
      );
  }

  return (
    <>
      <Alert intent="danger" title="Error during checkout.">
        {message}
      </Alert>

      <Spacing bottom="48" />
    </>
  );
};

ErrorAlert.displayName = 'ErrorAlert';
