import * as React from 'react';
import {
  initialize,
  LDClient,
  LDContext,
  LDOptions,
} from 'launchdarkly-js-client-sdk';

export const useLaunchDarklyInitialize = (
  clientId: string | null,
  user: LDContext,
  options?: LDOptions,
): LDClient | null => {
  const [client] = React.useState<LDClient | null>(() => {
    if (clientId === null || clientId === '') {
      return null;
    }
    return initialize(clientId, user, options);
  });

  React.useEffect(() => {
    if (client === null) {
      return;
    }

    return () => {
      void client.close();
    };
  }, [client]);

  return client;
};
