export const getExactMonths = (startDate: Date, endDate: Date) => {
  // Manually normalize both dates to start of day (midnight) to ignore time
  // Use UTC methods to extract components and create LOCAL dates at midnight
  const normalizedStartDate = new Date(
    startDate.getUTCFullYear(),
    startDate.getUTCMonth(),
    startDate.getUTCDate(),
  );
  const normalizedEndDate = new Date(
    endDate.getUTCFullYear(),
    endDate.getUTCMonth(),
    endDate.getUTCDate(),
  );

  if (normalizedStartDate > normalizedEndDate) {
    return 0;
  }

  const duration = intervalToDuration({
    start: normalizedStartDate,
    end: normalizedEndDate,
  });
  const totalMonths = (duration.years || 0) * 12 + (duration.months || 0);

  return totalMonths;
};

/*
 * Calculates the end date for the insurance policy based on the effective date and the default end date.
 * The end date is calculated by:
 * 1. Parsing the default end date to get the month and day
 * 2. Creating an end date using the effective date's year initially
 * 3. If the end date has passed the effective date, use next year
 * 4. If the difference is less than 6 months, use next year
 * 5. Format the end date as ISO string
 * 6. Remove milliseconds from the end date
 */
export const calculateEndDate = (
  effectiveDate: Date,
  defaultEndDate?: string,
): string | undefined => {
  if (!defaultEndDate) {
    return undefined;
  }

  // Parse defaultEndDate (assuming format like "2025-08-01")
  const parsedDefaultEndDate: Date = parse(
    defaultEndDate,
    'yyyy-MM-dd',
    new Date(),
  );
  if (isNaN(parsedDefaultEndDate.getTime())) {
    return undefined;
  }

  // Create end date using effective date's year initially
  parsedDefaultEndDate.setFullYear(effectiveDate.getFullYear());
  let endDate = parsedDefaultEndDate;

  // If the end date has passed the effective date, use next year
  if (endDate <= effectiveDate) {
    endDate = addYears(endDate, 1);
  }

  // Check if the difference is at least 6 months
  const totalMonths = getExactMonths(effectiveDate, endDate);
  if (totalMonths < 6) {
    endDate = addYears(endDate, 1);
  }

  // Format as ISO string
  return endDate.toISOString().replace(/\.[0-9]{3}Z$/, 'Z');
};

const mapGeneralInfoForm = (
  values: GeneralInfoFormValues,
  defaultProgram?: string,
  defaultEndDate?: string,
): Partial<InsurancePolicy & SubmissionLeadGen> => {
  // Use defaultProgram if distributionPrograms is empty and defaultProgram is available
  const distributionPrograms =
    values.distributionPrograms !== ''
      ? values.distributionPrograms
      : defaultProgram || '';

  return {
    email: values.email,
    phone_number: values.phoneNumber,
    first_name: values.firstName,
    last_name: values.lastName,
    name: values.companyName,
    domain_names:
      values.website?.replace(/\s/g, '').split(',').filter(Boolean) ?? [],
    effective_date: values.effectiveDate
      ?.toISOString()
      .replace(/\.[0-9]{3}Z$/, 'Z'),
    end_date: values.effectiveDate
      ? calculateEndDate(values.effectiveDate, defaultEndDate)
      : undefined,
    employee_count: values.employeeCount,
    address: {
      line_1: values.streetLine1 ?? '',
      line_2: values.streetLine2,
      city: values.city ?? '',
      state: values.state ?? '',
      country: 'US',
      postcode: values.zipcode ?? '',
      administrative_area: values.administrative_area ?? '',
      sub_administrative_area: values.sub_administrative_area ?? '',
    },
    industry_id: values.industry,
    revenue: {
      code: 'USD',
      amount: (values.companyRevenue || 0) * 100, // Convert to cents
    },
    gross_profit_net_revenue:
      values.grossProfitNetRevenue !== null
        ? {
            code: 'USD',
            amount: (values.grossProfitNetRevenue || 0) * 100, // Convert to cents
          }
        : null,
    affinity_referrer_uuid: values.affinityReferrerId,
    // Lead Gen Fields - https://fiasco.atlassian.net/browse/ENG-11127
    external_identifier: values.externalIdentifier,
    external_uuid: values.externalUuid,
    external_timestamp: values.externalTimestamp,
    distribution_programs:
      distributionPrograms !== '' ? [distributionPrograms] : [],
  };
};

const validateGeneralInfoFormField = (
  field: keyof GeneralInfoFormValues,
  value: GeneralInfoFormValues[keyof GeneralInfoFormValues],
  values: GeneralInfoFormValues,
  agencyProgramFlag: boolean,
) => {
  let error;

  if (field === 'companyName' && value === '') {
    error = 'Company name is required';
  }

  if (field === 'email' && typeof value === 'string') {
    if (value === '') {
      error = 'Email is required';
    }
    if (!validateEmail(value)) {
      error = 'Email is invalid';
    }
  }

  if (field === 'confirmEmail') {
    if (value === '') {
      error = 'Confirm email is required';
    }

    if (value !== values.email) {
      error = 'Email addresses must match';
    }
  }

  if (field === 'phoneNumber' && typeof value === 'string') {
    if (value === '') {
      error = 'Phone Number is required';
    }

    if (!isPhoneNumber(values.phoneNumber)) {
      error = 'Phone Number is invalid';
    }
  }

  if (field === 'website' && typeof value === 'string' && value !== '') {
    if (!isValidDomain(value)) {
      error = 'The provided domain name is invalid';
    }
  }

  if (field === 'noDomains' && !value && values.website === '') {
    error =
      'Please either enter a website domain or select "This company has no domains"';
  }

  if (field === 'industry' && (value === 0 || Number.isNaN(value))) {
    error = 'Industry is required';
  }

  if (
    field === 'companyRevenue' &&
    (value === 0 || (typeof value === 'number' && isNaN(value)))
  ) {
    error = 'Annual revenue is required';
  }

  if (field === 'streetLine1' && value === '') {
    error = 'Address line 1 is required';
  }

  if (field === 'city' && value === '') {
    error = 'City is required';
  }

  if (field === 'state' && value === '') {
    error = 'State is required';
  }

  if (field === 'zipcode' && value === '') {
    error = 'Zipcode is required';
  }

  if (field === 'firstName' && value === '') {
    error = 'First name is required';
  }

  if (field === 'lastName' && value === '') {
    error = 'Last name is required';
  }

  if (field === 'distributionPrograms' && value === '' && agencyProgramFlag) {
    error = 'Agency programs is required';
  }

  if (error !== undefined) {
    return {valid: false, error};
  }

  return {valid: true};
};

const transformGeneralInfoFormField = (
  field: keyof GeneralInfoFormValues,
  value: GeneralInfoFormValues[keyof GeneralInfoFormValues],
) => {
  if (field === 'zipcode' && value && typeof value === 'string') {
    return value.replace(/[^0-9]*/g, '').substr(0, 5);
  }

  if (field === 'website' && value && typeof value === 'string') {
    return value
      .replace(/\s/g, '')
      .split(',')
      .map((chunk) => extractDomainName(chunk))
      .join(', ');
  }

  if (field === 'industry' && value && typeof value === 'string') {
    return Number.parseInt(value, 10);
  }
  return value;
};

export type useGeneralInfoFormProps = {
  sessionId: string;
  initialValues: Partial<GeneralInfoFormValues>;
  validateOnMount?: boolean;
  editing?: boolean;
  agencyProgramFlag: boolean;
  defaultProgram?: string;
  defaultEndDate?: string;
};

// Used to translate server field validation failures to client side fields
const serverFieldMappings: Record<string, keyof GeneralInfoFormValues> = {
  url: 'website',
  domain_names: 'website',
  email: 'email',
  phone_number: 'phoneNumber',
  first_name: 'firstName',
  last_name: 'lastName',
};

export const getDefaultValues = (): GeneralInfoFormValues => ({
  affinityReferrerId: '',
  city: '',
  companyName: '',
  companyRevenue: 0,
  grossProfitNetRevenue: null,
  confirmEmail: '',
  effectiveDate: addDays(new Date(), 1),
  email: '',
  employeeCount: '1-25',
  industry: 0,
  phoneNumber: '',
  firstName: '',
  lastName: '',
  state: '',
  administrative_area: '',
  sub_administrative_area: '',
  streetLine1: '',
  streetLine2: '',
  website: '',
  noDomains: false,
  zipcode: '',
  externalIdentifier: '',
  externalUuid: '',
  externalTimestamp: '',
  distributionPrograms: '',
  renewalOfID: '',
});

export const useGeneralInfoForm = ({
  sessionId,
  initialValues,
  validateOnMount = false,
  editing: _editing = false,
  agencyProgramFlag,
  defaultProgram,
  defaultEndDate,
}: useGeneralInfoFormProps) => {
  const [formState, formActions] = useForm<
    GeneralInfoFormValues,
    Partial<InsurancePolicy>
  >({
    initialValues: {...initialValues},
    map: (values) => mapGeneralInfoForm(values, defaultProgram, defaultEndDate),
    transform: transformGeneralInfoFormField,
    validate: (field, value, values) =>
      validateGeneralInfoFormField(field, value, values, agencyProgramFlag),
    validateOnMount,
    defaultValues: getDefaultValues(),
  });
  const isMounted = React.useRef<boolean>(true);
  const inFlight = React.useRef<Promise<InsurancePolicy | void> | null>(null);
  const cachedValues = React.useRef<Partial<GeneralInfoFormValues> | null>(
    null,
  );
  const [, skuApi] = useSkuApi({session: sessionId});
  const [error, setError] = React.useState<Error | null>(null);
  const [busy, setBusy] = React.useState<boolean>(false);
  const [editing, setEditing] = React.useState<boolean>(_editing);

  React.useEffect(
    () => () => {
      isMounted.current = false;
    },
    [],
  );

  const state = {...formState, busy, editing, error};

  const actions = {
    ...formActions,
    /**
     * Toggle the busy flag
     */
    setBusy,
    /**
     * Set error state
     */
    setError,
    /**
     * Toggle the editing flags, caching the values if new value is true
     */
    setEditing: (isEditing: boolean) => {
      if (isEditing) {
        cachedValues.current = formState.values;
      }
      setEditing(isEditing);
    },
    /**
     * Create (or clone) the policy
     */
    save: () => {
      // Form isn't valid, do nothing
      const isValid = formActions.validateForm();
      if (!isValid) {
        return Promise.resolve();
      }

      // Request is already inflight, return that instead
      if (inFlight.current) {
        return inFlight.current;
      }

      setBusy(true);
      setError(null);

      // Call api method with mapped values
      const promise = skuApi
        .createInsurancePolicy(formActions.getOutput())
        .then((policy) => {
          if (policy) {
            return Promise.resolve(policy);
          }
          throw new UnknownErrorException();
        })
        .catch((err) => {
          if (err instanceof FormValidationError) {
            // Server validation error, update the form validation state
            // TODO: GET THIS WORKING
            err.keys.forEach((key) => {
              if (key in serverFieldMappings) {
                formActions.setFieldValidity(serverFieldMappings[key], false);
              } else {
                setError(err);
              }
            });
          } else {
            // Other errors can't really be handled, just set the error
            // so a message can be displayed
            setError(err);
          }
        })
        .finally(() => {
          setBusy(false);
          inFlight.current = null;
        });

      inFlight.current = promise;
      return promise;
    },
    /**
     * Reset the form values to any cached values (if set)
     */
    reset: () => {
      if (cachedValues.current) {
        formActions.setValues(cachedValues.current);
        cachedValues.current = null;
      }
    },
  };

  return [state, actions] as const;
};

export const getGeneralInfoValuesFromInsurancePolicy = (
  insurancePolicy: InsurancePolicy,
  affinityReferrerId: string,
  leadGenValues: Partial<GeneralInfoFormLeadGenFormValues> = {},
): GeneralInfoFormValues => ({
  ...getDefaultValues(),
  email: insurancePolicy.email,
  confirmEmail: insurancePolicy.email,
  companyName: insurancePolicy.name,
  phoneNumber: insurancePolicy.phone_number ?? '',
  firstName: insurancePolicy.first_name ?? '',
  lastName: insurancePolicy.last_name ?? '',
  streetLine1: insurancePolicy.address.line_1,
  streetLine2: insurancePolicy.address.line_2 || '',
  city: insurancePolicy.address.city,
  state: insurancePolicy.address.state,
  administrative_area: insurancePolicy.address.state,
  zipcode: insurancePolicy.address.postcode,
  website: insurancePolicy.domain_names.join(', '),
  industry: insurancePolicy.industry_id,
  companyRevenue: insurancePolicy.revenue
    ? insurancePolicy.revenue.amount / 100
    : 0,
  grossProfitNetRevenue:
    insurancePolicy.gross_profit_net_revenue !== null
      ? insurancePolicy.gross_profit_net_revenue.amount / 100
      : null,
  employeeCount: insurancePolicy.employee_count,
  effectiveDate: parse(
    insurancePolicy.effective_date.split('T')[0],
    'yyyy-MM-dd',
    new Date(),
  ),
  distributionPrograms:
    insurancePolicy.distribution_programs !== null
      ? insurancePolicy.distribution_programs.join(',')
      : '',
  renewalOfID: insurancePolicy.renewal_of_id || '',
  affinityReferrerId,
  ...leadGenValues,
});

export const getGeneralInfoValuesFromQueryParams = (
  params: URLSearchParams,
  affinityReferrerId: string,
): GeneralInfoFormValues => {
  const existingParams = [];
  params.forEach((_, key) => existingParams.push(key));
  if (existingParams.length <= 0) {
    const defaults = getDefaultValues();
    defaults.affinityReferrerId = affinityReferrerId;
    return defaults;
  }

  const mapParamToEmployeeCount = (params: URLSearchParams) => {
    const paramValue =
      (params.get('employee_count') as EmployeeCount) ?? '1-25';
    try {
      EmployeeCountSchema.check(paramValue);
      return paramValue;
    } catch (err) {
      return '1-25';
    }
  };

  return {
    email: params.get('email') ?? '',
    confirmEmail: params.get('email') ?? '',
    companyName: params.get('name') ?? '',
    phoneNumber: params.get('phone_number') ?? '',
    firstName: params.get('first_name') ?? '',
    lastName: params.get('last_name') ?? '',
    streetLine1: params.get('line_1') ?? '',
    streetLine2: params.get('line_2') ?? '',
    city: params.get('city') ?? '',
    state: params.get('state') ?? '',
    administrative_area: params.get('state') ?? '',
    sub_administrative_area: '',
    zipcode: params.get('postcode') ?? '',
    industry: parseInt(params.get('industry_id') ?? '0', 10),
    companyRevenue: parseInt(params.get('amount') ?? '0', 10),
    effectiveDate: addDays(new Date(), 1),
    grossProfitNetRevenue: null,
    website: params.get('domain_names') ?? '',
    noDomains: false,
    employeeCount: mapParamToEmployeeCount(params),
    affinityReferrerId,
    externalIdentifier: params.get('external_identifier') ?? '',
    externalUuid: params.get('external_uuid') ?? '',
    externalTimestamp: params.get('external_timestamp') ?? '',
    distributionPrograms: params.get('distribution_programs') ?? '',
    renewalOfID: params.get('renewal_of_id') ?? '',
  };
};
