import Monitoring from '@crucible-risk/react-monitoring';
import {useSentryIntegrations} from '@crucible-risk/use-sentry-integrations';
import type {PropsWithChildren, ReactElement} from 'react';
import React from 'react';
import {apiUrl, environment, segmentWriteKey} from '../../../config';

const datadogAllowedTracingOrigins: string[] = [new URL(apiUrl).origin];

export function AffinityMonitoring({
  children,
}: PropsWithChildren<unknown>): ReactElement {
  const sentryIntegrations = useSentryIntegrations();

  /**
    For all Monitoring the props see:
    https://github.com/crucible-risk/react-monitoring/blob/main/docs/PROPS.md

    Useful testing/debug flag props are:
    - datadogEnabled={true}
    Allows datadog in dev, specifically allows local env session replays to be sent to Datadog
    - sentryEnabled={true}
    Sends local Sentry errors
    - sentryDebug={true}
    Debug Sentry events in browser console
  */
  return (
    <Monitoring
      datadogAllowedTracingOrigins={datadogAllowedTracingOrigins}
      datadogApplicationId="89a52a8e-b35c-4a05-91b4-6e64d5b89340"
      datadogClientToken="pub8c06a2b59c19cbb511a498c676f9907e"
      datadogService="affinity"
      environment={environment}
      segmentEventPrefix="AFF"
      segmentWriteKey={segmentWriteKey}
      sentryDsn="https://5382b90397c84632b33a4e60414b0552@o78121.ingest.sentry.io/5230442"
      sentryIntegrations={sentryIntegrations}
      version={__BUILD_REVISION__}
    >
      {children}
    </Monitoring>
  );
}
