import {
  Attestations,
  InsurancePolicy,
  Invoice,
} from '@crucible-risk/sku-api-schema';
import {History} from 'history';

import {createClient} from '../../lib/api';
import {getSession} from '../../lib/session';
import {Preloader} from '../../lib/withPreloadedDataPage';
import {CreateQuotationException} from '../../lib/exceptions';

export interface CheckoutPageProps {
  attestationQuestions: Attestations;
  insurancePolicy: InsurancePolicy;
  invoice: Invoice;
  sessionId: string;
}
export type LoaderProps = {
  history: History;
};

export const checkoutPageDataLoader: Preloader<
  CheckoutPageProps,
  LoaderProps
> = (query: URLSearchParams, {history}): Promise<CheckoutPageProps> => {
  const sessionId = query.get('session');

  if (!sessionId) {
    throw new Error('no session id');
  }

  const client = createClient(getSession(sessionId));

  return client
    .getInvoice()
    .then((response) => {
      if (response.ok) {
        return response.data;
      }

      /**
       * If no invoice is available we need to re-request the quotation
       */
      return client.createQuotation().then((quotationResponse) => {
        if (quotationResponse.ok) {
          /**
           * Once we have the quotation we can get the invoice
           */
          return client.getInvoice().then((secondTryResponse) => {
            if (secondTryResponse.ok) {
              return secondTryResponse.data;
            }

            throw new Error('Failed to get invoice');
          });
        }

        throw new CreateQuotationException();
      });
    })
    .then((invoice) =>
      Promise.all([
        client.getInsurancePolicyAttestation().then((response) => {
          if (response.ok) {
            return response.data;
          }

          throw new Error('Failed to get attestation questions');
        }),

        client.getInsurancePolicy().then((response) => {
          if (response.ok) {
            return response.data;
          }

          throw new Error('Failed to get insurance policy data');
        }),
      ]).then(([attestationQuestions, insurancePolicy]) => {
        return {
          invoice,
          sessionId,
          attestationQuestions,
          insurancePolicy,
        };
      }),
    )
    .catch((error) => {
      /**
       * Redirect to confirmation page if there is a problem creating the quotation
       */
      if (error instanceof CreateQuotationException) {
        history.replace({
          pathname: history.location.pathname.replace(
            'checkout',
            'confirmation',
          ),
          search: history.location.search,
        });
      }

      throw error;
    });
};
