import {Record, Array, String, Number, Boolean, Static, Null} from 'runtypes';

// see: https://github.com/crucible-risk/webserver/blob/9fa5561/www/serializers/sku/industries.py#L5
export const IndustrySchema = Record({
  id: Number,
  name: String,
  gics_code: String,
  naics_codes: Array(String).Or(Null),
  uses_gross_profit_net_revenue: Boolean,
});

export type Industry = Static<typeof IndustrySchema>;
