import {useSegmentTrack} from '@crucible-risk/react-monitoring';
import React from 'react';

/*
When reflowing a JSON web token, this component mounts if the provided referrer
  is invalid. The props are only used for debugging.
*/

interface ReflowReferrerErrorProps {
  readonly jwt: string;
  readonly policyUuid: string;
  readonly referrerUuid: string;
}

export function ReflowReferrerError({
  jwt,
  policyUuid,
  referrerUuid,
}: ReflowReferrerErrorProps): React.ReactElement {
  // Contexts
  const track = useSegmentTrack();

  // Effects
  React.useEffect((): void => {
    void track('Reflow JWT referrer not found', {
      jwt,
      policyUuid,
      referrerUuid,
    });
  }, [jwt, policyUuid, referrerUuid, track]);

  return (
    <p>
      The referrer (<code>{referrerUuid}</code>) could not be found. The
      Affinity team has been notified of this incident. We apologize for the
      inconvenience.
    </p>
  );
}
