import {IStyle} from 'fela';
import {StyleFunction} from 'react-fela';

import {colors} from '@crucible-risk/theme';

export type StyleProps = {
  labelStyle: 'inline' | 'stacked';
  editing: boolean;
};

const STACKED_SHIM = 200;
const ROW_PAD = 8;

export const LABEL: StyleFunction<{}, StyleProps> = ({
  labelStyle = 'stacked',
}) => {
  const stacked = labelStyle === 'stacked';
  return {
    flexGrow: 0,
    flexShrink: 0,
    flexBasis: stacked ? undefined : STACKED_SHIM,
    alignSelf: stacked ? undefined : 'center',
  };
};

export const FORM: StyleFunction<{}, StyleProps> = () => {
  return {};
};

export const INPUT: StyleFunction<{}, StyleProps> = () => {
  return {
    flexGrow: 0,
    flexShrink: 1,
    flexBasis: '100%',
    nested: {
      '&:not(:first-of-type)': {
        paddingLeft: 4,
      },
      '&:not(:last-of-type)': {
        paddingRight: 4,
      },
    },
  };
};

export const INPUTS: StyleFunction<{}, StyleProps> = () => {
  return {
    display: 'flex',
    flexDirection: 'row',
    width: '100%',
  };
};

export const ERROR: StyleFunction<{}, StyleProps> = ({
  labelStyle = 'stacked',
}) => {
  const stacked = labelStyle === 'stacked';
  return {
    marginLeft: stacked ? 0 : STACKED_SHIM,
    marginTop: -ROW_PAD,
    marginBottom: ROW_PAD,
  };
};

export const INPUT_ROW: StyleFunction<{}, StyleProps> = ({
  labelStyle = 'stacked',
}) => {
  const stacked = labelStyle === 'stacked';
  return {
    display: 'flex',
    flexDirection: stacked ? 'column' : 'row',
    nested: {
      '&:not(:last-of-type)': {
        paddingBottom: ROW_PAD,
      },
    },
  };
};

export const INPUT_GROUP: StyleFunction<{}, StyleProps> = ({
  editing = false,
}) => {
  return {
    nested: {
      '&:not(:first-of-type)': {
        paddingTop: editing ? 24 : 8,
      },
    },
  };
};

export const ROW: IStyle = {
  display: 'flex',
  alignItems: 'flex-start',
  cursor: 'pointer',
};

export const DATE_PICKER_WRAPPER: IStyle = {
  nested: {
    '& .DayPicker-Day--today': {
      color: `${colors.blue500} !important`,
    },
    '& .DayPicker-Day': {
      padding: '0.35em 0.5em !important',
    },
  },
};
