import {useSentryCaptureException} from '@crucible-risk/react-monitoring';
import {InsurancePolicyResponse} from '@crucible-risk/sku-api-schema';
import React from 'react';
import {useHistory} from 'react-router-dom';
import {filterByNonNullable} from './utils/filterByNonNullable';
import {useSkuApi} from '/hooks/useSkuApi';
import {storeConfigurationId} from '/lib/session';
import {mapUnknownToString} from '/utils/mapUnknownToString';
import {ExpiredJwtError} from '/lib/exceptions';
import {LinkButton} from '@crucible-risk/button';
import {UseSupportChat} from '/lib/chat';

interface ReflowPolicyProps {
  readonly policyUuid: string;
  readonly referrer: string;
}

export function ReflowPolicy({policyUuid, referrer}: ReflowPolicyProps) {
  // Contexts
  const history = useHistory();
  const captureException = useSentryCaptureException();
  const {show: openChat} = UseSupportChat();

  // States
  const [error, setError] = React.useState<unknown>(null);
  const [, api] = useSkuApi({
    session: policyUuid,
  });

  const handleError = React.useCallback(
    (err: unknown): void => {
      setError(err);
      // Don't send ExpiredJwtError to Sentry - it's an expected error
      if (!(err instanceof ExpiredJwtError)) {
        captureException(err);
      }
    },
    [captureException],
  );

  const mapInsurancePolicyResponseToPathname = React.useCallback(
    ({
      lifecycle_state,
      selected_configuration,
    }: Partial<InsurancePolicyResponse>): string => {
      // If the quote is active or bound, the customer user is ready to checkout.
      if (
        lifecycle_state === 'QUOTATION_ACTIVE' ||
        lifecycle_state === 'BOUND'
      ) {
        return `/${referrer}/checkout`;
      }
      if (filterByNonNullable(selected_configuration)) {
        return `/${referrer}/confirmation`;
      }
      return `/${referrer}/select-plan`;
    },
    [referrer],
  );

  const handleSuccess = React.useCallback(
    (data: Partial<InsurancePolicyResponse>) => {
      // We must store the configuration ID because it will be needed to clone
      //   the policy when the customer makes changes to QA.
      if (filterByNonNullable(data.selected_configuration)) {
        storeConfigurationId(policyUuid, data.selected_configuration.id);
      }

      history.replace({
        pathname: mapInsurancePolicyResponseToPathname(data),
        search: `?session=${policyUuid}`,
      });
    },
    [history, mapInsurancePolicyResponseToPathname, policyUuid],
  );

  // Effects
  React.useEffect((): void => {
    if (error === null) {
      api.getInsurancePolicy().then(handleSuccess).catch(handleError);
    }
  }, [api, handleError, handleSuccess, error]);

  if (error !== null) {
    if (error instanceof ExpiredJwtError) {
      return (
        <>
          <p>This link has expired.</p>
          <p>
            Email links are valid for 60 days. Please{' '}
            <LinkButton onClick={openChat}>contact us</LinkButton> to request a
            new link.
          </p>
        </>
      );
    }

    return (
      <>
        <p>An error occurred loading your insurance policy.</p>
        <p>{mapUnknownToString(error)}</p>
        <p>
          The Affinity team has been notified of this incident. We apologize for
          the inconvenience. If you would like immediate assistance, please{' '}
          <LinkButton onClick={openChat}>contact us</LinkButton>.
        </p>
      </>
    );
  }

  return <>Loading...</>;
}
