import {History} from 'history';
import {Configuration} from '@crucible-risk/sku-api-schema';

import {createClient} from '../../lib/api';
import {clonePolicy} from '../../lib/clone-policy';
import {getSession} from '../../lib/session';
import {Preloader} from '../../lib/withPreloadedDataPage';
import {UnknownErrorException} from '../../lib/exceptions';

export interface SelectPlanPageProps {
  configurations: Array<Configuration>;
  sessionId: string;
}

export type LoaderProps = {
  history: History;
};

export const selectPlanPageDataLoader: Preloader<
  SelectPlanPageProps,
  LoaderProps
> = (query: URLSearchParams, {history}): Promise<SelectPlanPageProps> => {
  let sessionId = query.get('session') ?? '';
  if (!sessionId) {
    return Promise.reject(new Error('session-not-found'));
  }

  const client = createClient(getSession(sessionId));

  return client
    .getInsurancePolicy()
    .then((response) => {
      if (response.ok) {
        const policy = response.data;

        // If the policy is not in an incomplete state, it means the user has
        // likely hit back after attempting to issue their quote.  They cannot
        // edit it unless we recreate it with the same properties.
        if (policy.lifecycle_state !== 'INCOMPLETE') {
          return clonePolicy(policy).then((clonedPolicy) => {
            history.replace({
              pathname: history.location.pathname,
              search: `?session=${clonedPolicy.uuid}`,
            });
            sessionId = clonedPolicy.uuid;
            return clonedPolicy;
          });
        }

        return policy;
      }
      throw new UnknownErrorException();
    })
    .then(({insurance_market}) => {
      return client.getInsurancePolicyConfigurations().then((response) => {
        if (response.ok) {
          // If webserver has multiple configurations enabled for a referrer,
          // i.e. surplus and admitted, we only want to display configurations
          // that match the insurance_market of the incomplete quote.
          return response.data.filter((config) => {
            return config.insurance_market === insurance_market;
          });
        }

        throw new UnknownErrorException();
      });
    })
    .then((configurations) => {
      return {
        configurations,
        sessionId,
      };
    });
};
