import React from 'react';
import {useFela} from 'react-fela';
import {disableBodyScroll, enableBodyScroll} from 'body-scroll-lock';

import {useCombineRefs} from '@crucible-risk/combine-refs-hook';
import {useFocusScope, CloseHandler} from '@crucible-risk/focus-scope-hook';

import {sizes} from './dialog.config';

import {
  dialogStyle,
  containerStyle,
  wrapperStyle,
  closeButtonStyle,
  shadeStyle,
} from './dialog.fela';

interface Props extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * If `true`, the modal dialog is open.
   */
  open?: boolean;

  /**
   * Render a shaded layer behind the modal dialog.
   */
  shade?: boolean;

  /**
   * Render the dialog as a full-height "drawer" attached to the edge of the
   * viewport.
   */
  drawer?: boolean;

  /**
   * Set to `true` to lock the page scroll while the modal dialog is open.
   */
  preventScroll?: boolean;

  /**
   * Configure the width of the dialog.
   * @default "regular"
   */
  size?: keyof typeof sizes;

  /**
   * Optional react element positioned at the top-right of the modal dialog.
   */
  closeButton?: React.ReactNode;

  /**
   * When set to `true` the focus scope will automatically focus the first
   * tabbable child element when activated.
   *
   * Optionally provide a function which returns an html element to receive
   * focus.
   */
  setFocus?: boolean | ((element: HTMLElement) => HTMLElement | null);

  /**
   * Prevent mouse and keyboard events from propagating outside of modal dialog
   * element.
   */
  cancelEvents?: boolean;

  /**
   * Close callback. Called when the user clicks or focuses outside the modal
   * dialog element, or presses the esc key.
   */
  onClose?: CloseHandler;

  /**
   * Prevent focus from leaving the modal dialog element. When set, focus events
   * targeting elements outside the modal dialog element will be redirected
   * within, tab focus navigation will cycle within the modal dialog element,
   * and click event default behavior outside the modal dialog element will be
   * prevented.
   */
  trapFocus?: boolean;
}

export const DialogRefComponent = (
  props: Props,
  ref: React.Ref<HTMLDivElement>,
) => {
  const {
    open,
    setFocus,
    cancelEvents,
    onClose,
    trapFocus,
    children,
    size,
    shade,
    closeButton,
    preventScroll,
    drawer,
    ...rest
  } = props;

  const shadeRef = React.useRef<HTMLDivElement | null>(null);

  const handlePointer = (event: Parameters<CloseHandler>[0]) => {
    if (onClose && event.target === shadeRef.current) {
      onClose(event, 'pointer');
    }
  };

  const focusScopeRef = useFocusScope({
    onMouseDown: handlePointer,
    onTouchStart: handlePointer,
    onClose,
    trapFocus,
    setFocus,
    cancelEvents,
  });

  const elementRef = React.useRef<HTMLDivElement | null>(null);

  const scrollLockRef = React.useCallback(
    (element: HTMLDivElement | null) => {
      if (elementRef.current && preventScroll) {
        enableBodyScroll(elementRef.current);
      }

      elementRef.current = element;

      if (elementRef.current && preventScroll) {
        disableBodyScroll(elementRef.current);
      }
    },
    [preventScroll],
  );

  const {css} = useFela({size, shade, drawer});

  const combinedRef = useCombineRefs(focusScopeRef, scrollLockRef, ref);

  if (!open) {
    return null;
  }

  return (
    <div
      ref={combinedRef}
      {...rest}
      role="dialog"
      aria-modal
      className={css(containerStyle)}
    >
      <div ref={shadeRef} className={css(shadeStyle)}>
        <div className={css(wrapperStyle)}>
          <div className={css(dialogStyle)}>
            {!!closeButton && (
              <div className={css(closeButtonStyle)}>{closeButton}</div>
            )}
            {children}
          </div>
        </div>
      </div>
    </div>
  );
};

export const Dialog = React.forwardRef(DialogRefComponent);

export type DialogAttributes = JSX.LibraryManagedAttributes<
  typeof Dialog,
  Props
>;
