import axios from 'axios';
import {ApiClientBase, Options} from '@crucible-risk/api-client-base';
import {withSku} from '@crucible-risk/sku-api-client';
import {apiUrl} from '../config';
import {affinityReferrerUUID} from '/hooks/useAffinityReferrer';

const APIClient = withSku(ApiClientBase);

export const createClient = (jwt?: string) => {
  const options: Options = {
    baseUrl: apiUrl,
    getAccessToken: () => jwt,
    onValidationError: (error) => {
      if (__DEV__) {
        throw error;
      }
      if (typeof window.Sentry !== 'undefined') {
        window.Sentry.withScope((scope) => {
          scope.setExtra('url', error.response.config?.url);
          scope.setExtra('status', error.response.status);
          scope.setExtra('code', error.code);
          window.Sentry?.captureException(error);
        });
      }
    },
  };

  if (affinityReferrerUUID) {
    options.axios = axios.create({
      headers: {
        'X-Affinity-Referrer': affinityReferrerUUID,
      },
    });
  }

  return new APIClient(options);
};
