import React from 'react';
import {useFela} from 'react-fela';

import {Container} from '@crucible-risk/container';
import {Typography as T} from '@crucible-risk/typography';
import {Spacing} from '@crucible-risk/spacing';
import {Button} from '@crucible-risk/button';
import {TextInput} from '@crucible-risk/text-input';
import {InsurancePolicy, Invoice} from '@crucible-risk/sku-api-schema';

import {formatCurrency} from '../../../utils/intl';
import {Responsive} from '../../Responsive';
import {Steps} from '../../Steps';
import {Sidebar} from '../../Sidebar';
import {ContentPanel} from '../../ContentPanel';
import {
  AttestationQuestions,
  Props as AttestationQuestionsProps,
  Data as QuestionData,
} from '../../AttestationQuestions';
import {CheckoutPageType} from '../../../lib/content';
import {Icon} from '../../Icon';

import {SIDEBAR, MAIN} from './styles';
import {PaymentCardForm, PaymentCardData} from '../../PaymentCardForm';
import {FormData as LibFormData} from '../../../lib/form';
import {ErrorAlert} from './ErrorAlert';
import {Redacted} from '../../Redacted';

export interface FormData extends PaymentCardData, LibFormData, QuestionData {
  signature: string;
  email: string;
}

export type SignatureData = string;

type CheckoutProps = {
  loading: boolean;
  sessionId: string;
  content: CheckoutPageType;
  changePlanLink: string;
  plan: InsurancePolicy;
  quoteDocumentUuid?: string | null;
  quoteDocumentName: string | null;
  card: PaymentCardForm;
  attestation: Partial<AttestationQuestionsProps> &
    Pick<AttestationQuestionsProps, 'error'>;
  pay: {
    enabled: boolean;
    onClick: () => void;
  };
  signature: {
    label?: string;
    placeholder?: string;
    data: string;
    error?: string;
  };
  onChange: any;
  error?: string;
  onOpenContact: () => void;
  invoice: Invoice;
};

export const Checkout = ({
  loading,
  sessionId,
  content,
  quoteDocumentUuid,
  quoteDocumentName,
  changePlanLink,
  plan,
  card,
  attestation,
  pay,
  signature,
  onChange,
  error,
  onOpenContact,
  invoice,
}: CheckoutProps) => {
  const {css} = useFela();

  return (
    <Container>
      <Spacing bottom="56" />

      <Steps>
        <Steps.Step title="General Info" status="finished" />
        <Steps.Step title="Select a Plan" status="finished" />
        <Steps.Step title="Confirmation" status="finished" />
        <Steps.Step title="Checkout" status="active" />
      </Steps>

      <Spacing bottom="56" />

      {error && <ErrorAlert error={error} onOpenContact={onOpenContact} />}

      <T
        className="h1 fg-title"
        variant="displaySmall"
        fill
        align="center"
        color="black"
        weight="semibold"
      >
        {content.heading}
      </T>
      <Spacing top="48" bottom="32">
        <Responsive>
          <Responsive.Column
            className={css(SIDEBAR)}
            style={{flexBasis: '34%'}}
          >
            <Spacing bottom="32">
              <Sidebar
                sessionId={sessionId}
                content={content.selected}
                planTitle={plan.name}
                limit={plan.limit}
                deductible={plan.retention}
                effectiveDate={plan.effective_date}
                endDate={plan.end_date}
                quoteDocumentUuid={quoteDocumentUuid}
                quoteDocumentName={quoteDocumentName}
                changePlanLink={changePlanLink}
                total={invoice.balance_total}
                priceBreakdown={invoice.price_breakdown}
              />
            </Spacing>
          </Responsive.Column>

          <Responsive.Column className={css(MAIN)} style={{flexBasis: '66%'}}>
            <Responsive>
              <Responsive.Column style={{flexBasis: '30%'}}>
                <Spacing bottom="16">
                  <T
                    className="body2 fg-title"
                    fill
                    variant="bodyLarge"
                    weight="semibold"
                    color="black"
                  >
                    {content.payment.label}
                  </T>
                </Spacing>
              </Responsive.Column>

              <Responsive.Column style={{flexBasis: '70%'}}>
                <Spacing bottom="32">
                  <PaymentCardForm
                    countries={card.countries}
                    data={card.data}
                    onChange={onChange}
                    error={card.error}
                  />
                </Spacing>
              </Responsive.Column>
            </Responsive>

            <Responsive>
              <Responsive.Column style={{flexBasis: '30%'}}>
                <Spacing bottom="16">
                  <T
                    className="body2 fg-title"
                    fill
                    variant="bodyLarge"
                    weight="semibold"
                    color="black"
                  >
                    {content.review.label}
                  </T>
                </Spacing>
              </Responsive.Column>

              <Responsive.Column style={{flexBasis: '70%'}}>
                <Spacing bottom="32">
                  <AttestationQuestions
                    questions={attestation.questions}
                    data={attestation.data}
                    onChange={onChange}
                    content={content}
                    error={attestation.error}
                  />
                </Spacing>

                <Spacing bottom="16">
                  <T
                    className="body3 fg-title"
                    weight="semibold"
                    color="black"
                    fill
                  >
                    {signature.label ??
                      'Type in your full name to sign and attest to these terms.'}
                  </T>
                </Spacing>

                <Spacing bottom="32">
                  <Redacted>
                    <TextInput
                      value={signature.data}
                      onChange={(value) => onChange('signature', value)}
                      placeholder={signature.placeholder ?? 'Enter your name'}
                      intent={
                        signature.error === undefined ? 'neutral' : 'danger'
                      }
                    />
                  </Redacted>
                  {signature.error !== undefined && (
                    <T color="red500" variant="bodySmall">
                      {signature.error}
                    </T>
                  )}
                </Spacing>

                <Spacing bottom="16">
                  <Button
                    className="fg-inverted bg-primary"
                    fill
                    disabled={!pay.enabled || loading}
                    onClick={pay.onClick}
                    loading={loading}
                    sharpCorners
                  >
                    {content.payment.label}
                  </Button>
                </Spacing>

                {plan.premium && (
                  <Spacing bottom="24">
                    <T
                      fill
                      className="body3 fg-title"
                      variant="bodyRegular"
                      weight="semibold"
                      color="black"
                      align="center"
                    >
                      {content.review.footer.replace(
                        '{total}',
                        formatCurrency(invoice.balance_total.amount / 100, {
                          currency: invoice.balance_total.code,
                          fractionDigits: 2,
                        }),
                      )}
                    </T>
                  </Spacing>
                )}
              </Responsive.Column>
            </Responsive>
          </Responsive.Column>
        </Responsive>

        <Spacing vertical="48">
          <ContentPanel.Divider />
        </Spacing>

        <ContentPanel title={content.footer.heading}>
          <ContentPanel.Row3Items
            content={content.footer.content.map((item) => {
              return (
                <ContentPanel.Item
                  icon={<Icon icon={item.icon} />}
                  title={item.heading}
                  description={item.body}
                />
              );
            })}
          />
        </ContentPanel>
      </Spacing>
    </Container>
  );
};
