import React from 'react';

import {
  PatchIcon,
  ComputerErrorIcon,
  PasswordIcon,
  TheftIcon,
  PhishingIcon,
  WireFraudIcon,
  CoalitionIcon,
  CoinsIcon,
  ShieldCheckIcon,
} from '@crucible-risk/icon';

interface Props {
  icon: string;
}

export const Icon: React.FC<Props> = ({icon}) => {
  switch (icon) {
    case 'PatchIcon':
      return <PatchIcon />;

    case 'ComputerErrorIcon':
      return <ComputerErrorIcon />;

    case 'PasswordIcon':
      return <PasswordIcon />;

    case 'TheftIcon':
      return <TheftIcon />;

    case 'PhishingIcon':
      return <PhishingIcon />;

    case 'WireFraudIcon':
      return <WireFraudIcon />;

    case 'CoalitionIcon':
      return <CoalitionIcon />;

    case 'CoinsIcon':
      return <CoinsIcon />;

    case 'ShieldCheckIcon':
      return <ShieldCheckIcon />;

    default:
      return null;
  }
};
