import * as React from 'react';
import {Stripe, StripeElements, Token} from '@stripe/stripe-js';
import {CardNumberElement} from '@stripe/react-stripe-js';
import {saveAs} from 'file-saver';

import {Currency} from '@crucible-risk/sku-api-schema';

import {createClient} from '../../lib/api';
import {getSession} from '../../lib/session';

export const downloadQuotation = (
  documentUuid: string,
  quotationDocumentName: string,
  sessionId: string,
  endLoading: () => void,
) => {
  const jwt = getSession(sessionId);
  const client = createClient(jwt);

  client
    .downloadInsurancePolicyDocument(documentUuid)
    .then((response) => {
      endLoading();

      if (response.ok) {
        return response.data as any;
      }

      throw new Error('document-error');
    })
    .then((content) => {
      const blob = new Blob([content], {
        type: 'application/pdf',
      });

      saveAs(blob, quotationDocumentName);
    });
};

class StripeError extends Error {
  type = '';

  constructor(type: string, message: string) {
    super();

    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, StripeError);
    }

    this.name = 'StripeError';

    this.type = type;
    this.message = message;
  }
}

const getStripeCardNumberElement = (
  stripe: Stripe | null,
  elements: StripeElements | null,
) => {
  if (!stripe || !elements) {
    return null;
  }

  return elements.getElement(CardNumberElement);
};

export const stripeCreateToken = (
  stripe: Stripe | null,
  elements: StripeElements | null,
  {
    name,
    address_zip,
    address_country,
  }: {
    name: string;
    address_zip: string;
    address_country: string;
  },
  endLoading: () => void,
) => {
  return new Promise<Token>((resolve, reject) => {
    const cardElement = getStripeCardNumberElement(stripe, elements);

    if (!cardElement) {
      return reject(new StripeError('pageError', 'No stripe elements found'));
    }

    return stripe
      ?.createToken(cardElement, {
        name,
        address_zip,
        address_country,
      })
      .then((stripeResponse) => {
        if (stripeResponse.token) {
          return resolve(stripeResponse.token);
        }

        if (
          stripeResponse.error &&
          stripeResponse.error.type === 'validation_error' &&
          stripeResponse.error.message
        ) {
          reject(new StripeError('stripeError', stripeResponse.error.message));
        }

        throw stripeResponse;
      })
      .catch(() => {
        endLoading();
        reject(new StripeError('pageError', 'Stripe response error'));
      });
  });
};

export interface Data {
  amount: Currency;
  name: string;
  address_country: string;
  address_zip: string;
  email: string;
  attestation_terms: boolean;
  attestation_legal: boolean;
  signature: string;
  auto_renewal: boolean;
}

interface HandlePayment {
  data: Data;
  sessionId: string;
  stripe: Stripe | null;
  elements: StripeElements | null;
  gotoSuccess: () => void;
  setPageError: (message?: string) => void;
  setStripeError: (message?: string) => void;
  openModal: () => void;
  closeModal: () => void;
  endLoading: () => void;
  openChat: () => void;
  retryStartTime: React.MutableRefObject<number | null>;
  setIsSlow: (isSlow: boolean) => void;
}

/**
 * This handles getting a Stripe token and using that, the form data
 * the policy info, and the invoice info to pay for the policy.
 */
export function handlePayment({
  data,
  sessionId,
  stripe,
  elements,
  gotoSuccess,
  setPageError,
  setStripeError,
  openModal,
  closeModal,
  endLoading,
  openChat,
  retryStartTime,
  setIsSlow,
}: HandlePayment) {
  const jwt = getSession(sessionId);
  const client = createClient(jwt);

  closeModal();

  const handleError = (error: {type: string; message: string}) => {
    switch (error.type) {
      case 'stripeError':
        return setStripeError(error.message);

      case 'paymentError':
        return setPageError('payment-error');

      case 'licenseError':
        return setPageError('license-error');

      case 'effectiveDateTooFar':
        return setPageError('effective-date-too-far');

      default:
      case 'pageError':
        return setPageError('generic');
    }
  };

  setPageError();
  setStripeError();

  stripeCreateToken(
    stripe,
    elements,
    {
      address_zip: data.address_zip,
      address_country: data.address_country,
      name: data.name,
    },
    endLoading,
  )
    .then((token) => {
      /**
       * Pay the policy using api-client
       */
      client
        .payInsurancePolicy({
          amount: data.amount,
          payment_processor_token: token.id,
          attestation_terms: data.attestation_terms,
          attestation_legal: data.attestation_legal,
          signature: data.signature,
        })
        .then((clientResponse) => {
          if (clientResponse.ok && clientResponse.status === 200) {
            gotoSuccess();
          }

          throw clientResponse;
        })
        .catch((error) => {
          if (!error.data) {
            endLoading();
            return handleError({
              type: 'pageError',
              message: 'Response has no data',
            });
          }

          if (
            error.data.code === 400 &&
            error.data.message &&
            error.data.message.payment_processor
          ) {
            endLoading();
            return handleError({
              type: 'paymentError',
              message: 'payment-error',
            });
          }

          // Handle 400 Quote is in secondary review special case
          if (
            error.status === 400 &&
            error.data?.errors?.[0]?.code === 'quote-secondary-review'
          ) {
            endLoading();
            window.location.href =
              window.location.pathname.replace('checkout', 'secondary-review') +
              window.location.search;
            return Promise.reject(error);
          }

          if (
            error.status === 400 &&
            error.data?.errors?.[0]?.code === 'invalid-license'
          ) {
            openChat();
            endLoading();
            return handleError({
              type: 'licenseError',
              message: 'Invalid license',
            });
          }

          // Handle 400 effective date too far special case
          if (
            error.status === 400 &&
            error.data?.errors?.[0]?.code === 'effective-date-too-far'
          ) {
            endLoading();
            return handleError({
              type: 'effectiveDateTooFar',
              message: 'Effective date too far',
            });
          }

          // Handle 400 underwriting-incomplete special case
          if (
            error.status === 400 &&
            error.data?.errors?.[0]?.code === 'underwriting-incomplete'
          ) {
            const now = Date.now();

            // Initialize retry start time if this is the first retry
            if (retryStartTime.current === null) {
              retryStartTime.current = now;
            }

            // Check if 5 minutes (300,000 ms) have elapsed
            const elapsedTime = now - retryStartTime.current;
            const maxRetryTime = 5 * 60 * 1000;

            if (elapsedTime < maxRetryTime) {
              // Show underwriting review message
              setIsSlow(true);
              // Retry after 10 seconds
              // Keep loading state during retry
              return new Promise<void>((resolve) => {
                window.setTimeout(() => {
                  handlePayment({
                    data,
                    sessionId,
                    stripe,
                    elements,
                    gotoSuccess,
                    setPageError,
                    setStripeError,
                    openModal,
                    closeModal,
                    // Pass a no-op for endLoading during retry to maintain loading state
                    endLoading: () => {},
                    openChat,
                    retryStartTime,
                    setIsSlow,
                  });
                }, 10000);
              });
            } else {
              // After 5 minutes of retries, log to Sentry and redirect to error page
              window.Sentry?.withScope((scope) => {
                scope.setExtras({
                  data: error.data,
                  elapsedTime,
                  maxRetryTime,
                });
                window.Sentry?.captureException(error);
              });

              // Reset states
              retryStartTime.current = null;
              setIsSlow(false);

              // Redirect to error page
              window.location.href =
                window.location.pathname.replace('checkout', 'error') +
                window.location.search;

              return Promise.reject(error);
            }
          }

          // Handle 409 email special case
          if (error.data.code === 409 && error.data.reason === 'email') {
            endLoading();
            return openModal();
          }

          // Other responses show message in page
          endLoading();
          return handleError({
            type: 'pageError',
            message: error.data.message,
          });
        });
    })
    .catch((error) => {
      endLoading();
      return handleError(error);
    });
}
