import {
  Boolean,
  Record,
  String,
  Null,
  Number,
  Partial,
  Union,
  Literal,
  Array,
  Static,
  Optional,
} from 'runtypes';

import {LifecycleStateSchema} from './lifecycleState';
import {BrokerSchema} from './broker';
import {MarketSchema} from './market';
import {PolicyVersionSchema} from './policyVersion';
import {InsuranceProgramSchema} from './insuranceProgram';
import {W2RAssociationSchema} from './w2rAssociation';

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L540
const YesNoSchema = Union(Literal('Yes'), Literal('No'));

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L546
const YesNoSometimesSchema = Union(YesNoSchema, Literal('Sometimes'));

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L581-L591
const ClausesSchema = Partial({
  BINDING_ARBITRATION: Boolean,
  CUSTOMER_SIGN_OFF: Boolean,
  DISCLAIMER_OF_WARRANTIES: Boolean,
  EXCLUSION_OF_DAMAGES: Boolean,
  HOLD_HARMLESS_AGREEMENTS: Boolean,
  INDEMNIFICATION: Boolean,
  LIMITATION_OF_LIABILITY: Boolean,
  MILESTONES: Boolean,
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L609
const ResponsesSchema = Partial({
  aware_of_new_claims_explanation: String,
  aware_of_new_claims: YesNoSchema,
  backup_and_restore: YesNoSchema,
  cc_customer_count: Union(String, Number),
  content_complaints: YesNoSchema,
  dual_control: YesNoSchema,
  encrypts_data: YesNoSometimesSchema,
  has_eo_mpl: YesNoSchema,
  has_tech_eo: YesNoSchema,
  is_msp_or_bad_industry: YesNoSchema,
  mitigating_clauses: ClausesSchema,
  pii_phi_count: Union(String, Number),
  pii_phi: YesNoSchema,
  prior_claims_explanation: String,
  prior_claims: String,
  professional_services: String,
  reviews_content: YesNoSchema,
  services_by_contract: String,
  tech_eo_changes_description: String,
  tech_eo_changes: YesNoSchema,
  tech_eo_dispute_explanation: String,
  tech_eo_dispute: YesNoSchema,
  wants_tech_eo: YesNoSchema,
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L461
const BinderSchema = Record({
  binder_period_end_date: String,
  created_at: String,
  nj_transaction_number: String.Or(Null),
  signing_allowed_by_date: String,
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/address.py#L9
const AddressSchema = Record({
  city: String.Or(Null),
  postcode: String.Or(Null),
  state: String.Or(Null),
  street_line_1: String.Or(Null),
  street_line_2: String.Or(Null),
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/industry.py#L15
const IndustrySchema = Record({
  display_name: String,
  id: Number,
  reject_business_interruption: Boolean,
  reject_ftf: Boolean,
  reject_media_liability: Boolean,
  reject_tech_eo: Boolean,
  require_eo_mpl: Boolean,
  require_tech_eo: Boolean,
  use_gross_profit_net_revenue: Boolean,
});

// see: https://github.com/crucible-risk/webserver/blob/3c5fac2/www/serializers/desired_policy.py#L112
const CoverageSchema = Record({
  sublimit: Number.Or(Null),
  subretention: Number.Or(Null),
});

// see: https://github.com/crucible-risk/servers_common/blob/298c62b/common/models/coverages.py#L22
const CoveragesSchema = Partial({
  network: CoverageSchema,
  regulatory_defense: CoverageSchema,
  media_liability: CoverageSchema,
  pci: CoverageSchema,
  breach_response: CoverageSchema,
  breach_response_costs: CoverageSchema,
  breach_response_services: CoverageSchema,
  crisis_management: CoverageSchema,
  extortion: CoverageSchema,
  business_interruption: CoverageSchema,
  asset_restoration: CoverageSchema,
  funds_transfer: CoverageSchema,
  reputation: CoverageSchema,
  systems_integrity: CoverageSchema,
  computer_replacement: CoverageSchema,
  service_fraud: CoverageSchema,
  bipd_first_party: CoverageSchema,
  bipd_third_party: CoverageSchema,
  pollution: CoverageSchema,
  tech_eo: CoverageSchema,
  reputational_harm: CoverageSchema,
  funds_transfer_liability: CoverageSchema,
  phishing: CoverageSchema,
  invoice_manipulation: CoverageSchema,
  proof_of_loss: CoverageSchema,
  court_attendance: CoverageSchema,
  criminal_reward: CoverageSchema,
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L342
const DocumentSchema = Record({
  created_at: String,
  id: Number,
  label: String,
  name: String,
  pdf_type: String,
  updated_at: String.Or(Null),
  url: String,
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L844
const CreatorSchema = Record({
  email: String.Or(Null),
  id: Number,
  name: String.Or(Null),
  uuid: String.Or(Null),
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L358
const EndorsementSchema = Record({
  deletable: Boolean,
  effective_date: String,
  endorsement_type: String,
  form_code: String.Or(Null),
  id: Number,
  index: Number,
  label: String,
  link: String.Or(Null),
  pdf_id: Number.Or(Null),
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/policyholder.py#L11
const PolicyholderSchema = Record({
  address: AddressSchema.Or(Null),
  email: String,
  name: String.Or(Null),
  phone_number: String.Or(Null),
  uuid: String,
});

// see: https://github.com/crucible-risk/servers_common/blob/298c62b/common/models/models_quote.py#L150
const DocumentKindSchema = Union(
  Literal('QUOTATION'),
  Literal('BINDER'),
  Literal('POLICY'),
);

// see: https://github.com/crucible-risk/servers_common/blob/298c62b/common/models/models_policy.py#L17
const RenewalStatusSchema = Union(
  Literal('ACTION_REQUIRED'),
  Literal('AUTOMATIC_RENEWAL'),
  Literal('AUTOMATIC_RENEWAL_READY'),
  Literal('MANUAL_RENEWAL'),
  Literal('NO_RENEWAL_CARRIER_DECISION'),
  Literal('NO_RENEWAL_COALITION_DECISION'),
  Literal('NO_RENEWAL_COALITION_NON_RENEWAL'),
  Literal('NO_RENEWAL_COALITION_UNFULFILLED_CONTINGENCIES'),
  Literal('NO_RENEWAL_COMPETITOR_BETTER_BUNDLE'),
  Literal('NO_RENEWAL_COMPETITOR_BETTER_COVERAGE'),
  Literal('NO_RENEWAL_COMPETITOR_BETTER_PRICING'),
  Literal('NO_RENEWAL_COMPETITOR_UNKNOWN'),
  Literal('NO_RENEWAL_OTHER'),
  Literal('NO_RENEWAL_POLICYHOLDER_ASSUMED'),
  Literal('NO_RENEWAL_POLICYHOLDER_DECISION'),
  Literal('NO_RENEWAL_POLICYHOLDER_M_A'),
  Literal('NO_RENEWAL_POLICYHOLDER_NO_COVERAGE_PURCHASED'),
  Literal('NO_RENEWAL_POLICYHOLDER_NOT_IN_BUSINESS'),
  Literal('NO_RENEWAL_POLICYHOLDER_UNKNOWN'),
  // Sigh. https://fiasco.atlassian.net/browse/OMG-1216
  Literal(''),
);

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L474
const PolicySchema = Record({
  renewal_status: RenewalStatusSchema.Or(Null),
  terminated_date: String.Or(Null),
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L390
const QuoteSchema = Record({
  archived: Boolean,
  contingent: Boolean,
  declined: Boolean,
  expires_on: String,
  required_bind_fields: Array(String),
  surplus_lines_agent_number: String.Or(Null),
  unbindable_reasons: Array(String),
  under_review: Boolean,
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L137
const RenewalSchema = Record({
  coalition_policy_number: String,
  lifecycle_state: LifecycleStateSchema,
  renewal_status: RenewalStatusSchema.Or(Null),
  uuid: String,
});

// https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/desired_policy.py#L754
const RenewalQuoteSchema = Record({
  application_sent: Boolean,
  coalition_policy_number: String,
  lifecycle_state: LifecycleStateSchema,
  quote_emailed: Boolean,
  uuid: String,
});

// see: https://github.com/crucible-risk/servers_common/blob/298c62b/common/models/surcharges.py#L5
const SurchargeTypeSchema = Union(
  Literal('STATE_TAX'),
  Literal('STATE_FEE'),
  Literal('STATE_FILING_FEE'),
  Literal('STAMPING_FEE'),
  Literal('BROKER_FEE'),
  Literal('RPG_FEE'),
  Literal('MWUA_FEE'),
  Literal('FIRE_FEE'),
  Literal('ADMIN_FEE'),
);

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/surcharge.py#L93
const SurchargeSchema = Record({
  amount: Number,
  desired_policy_uuid: String,
  label: String,
  surcharge_rule_uuid: String,
  type: SurchargeTypeSchema,
});

// see: https://github.com/crucible-risk/webserver/blob/33746a7/www/serializers/desired_policy.py#L800-L867
export const PackageSchema = Record({
  account_uuid: String.Or(Null),
  aggregate_limit: Number.Or(Null),
  aggregate_retention: Number.Or(Null),
  application_responses: ResponsesSchema,
  binder: BinderSchema.Or(Null),
  broker: BrokerSchema,
  coalition_policy_number: String.Or(Null),
  company_address: AddressSchema.Or(Null),
  company_employee_count: String.Or(Null),
  company_gross_profit_net_revenue: Number.Or(Null),
  company_industry: IndustrySchema.Or(Null),
  company_name: String.Or(Null),
  company_revenue: Number.Or(Null),
  continuity_date: String.Or(Null),
  coverage_instances: CoveragesSchema,
  created_at: String.Or(Null),
  created_by: CreatorSchema,
  currency_code: String,
  default_retention: Number.Or(Null),
  documents: Array(DocumentSchema),
  domain_names: Array(String),
  effective_date: String.Or(Null),
  end_date: String.Or(Null),
  insurance_market: MarketSchema,
  intended_policyholder: PolicyholderSchema.Or(Null),
  kind: DocumentKindSchema.Or(Null),
  lifecycle_state: LifecycleStateSchema,
  max_suggested_limit: Number.Or(Null),
  per_event_limit_liability: Number.Or(Null),
  policy: PolicySchema.Or(Null),
  policy_version: PolicyVersionSchema,
  premium: Number.Or(Null),
  program: InsuranceProgramSchema,
  quote: QuoteSchema.Or(Null),
  renewal_of: RenewalSchema.Or(Null),
  renewal_quotes: Array(RenewalQuoteSchema),
  requires_review: Boolean,
  retroactive_date: String.Or(Null),
  should_display_surcharges: Boolean,
  should_email_policyholder: Boolean,
  surcharges: Array(SurchargeSchema),
  underwriting_complete: Boolean,
  updated_at: String.Or(Null),
  uuid: String,
  endorsements: Optional(Array(EndorsementSchema)),
  tags: Optional(Array(String)),
  w2r_association_id: Optional(String.Or(Null)),
  // NOTE: This is a virtual field and does not come from the API.
  // My opinion is that it probably should, so this is a way of
  // faking that behaviour until maybe one day the API does the
  // right thing.
  w2r_association: Optional(W2RAssociationSchema.Or(Null)),
});

export type Package = Static<typeof PackageSchema>;
