import React from 'react';

import {useUniqueId} from '@crucible-risk/unique-id-hook';
import {Typography} from '@crucible-risk/typography';
import {TextInput} from '@crucible-risk/text-input';
import {Button} from '@crucible-risk/button';
import {Spacing} from '@crucible-risk/spacing';
import {Dialog} from '@crucible-risk/dialog';

import {Redacted} from '../Redacted';

export const EmailDialog: React.FC<{
  open: boolean;
  email: string;
  onChange: (value: string) => void;
  onButtonClick: () => void;
  loading: boolean;
  error?: string;
}> = ({open, email, onChange, onButtonClick, loading, error}) => {
  const labelId = useUniqueId();

  return (
    <Dialog
      shade
      open={open}
      aria-labelledby={labelId}
      size="small"
      trapFocus
      onClose={() => {}}
    >
      <Spacing around="48">
        <Typography align="center" id={labelId}>
          Email address is already taken. Please enter a new email address.
        </Typography>

        <Spacing bottom="16" />

        <Redacted>
          <TextInput
            value={email}
            onChange={onChange}
            placeholder="Email Address"
            intent={error === undefined ? 'neutral' : 'danger'}
          />
        </Redacted>
        {error !== undefined && (
          <Typography color="red500" variant="bodySmall">
            {error}
          </Typography>
        )}

        <Spacing bottom="16" />

        <Button
          label="Submit"
          loading={loading}
          disabled={error !== undefined}
          onClick={onButtonClick}
        />
      </Spacing>
    </Dialog>
  );
};
